// 9b. PATCH /api/project/:projectId/firewalls/:firewallName -> Edit, Toggle Enable/Disable, Change ALLOW/DENY, Priority, Ranges, Tags & Logging on Live GCP Firewall Rule
app.patch('/api/project/:projectId/firewalls/:firewallName', async (req, res) => {
  const { projectId, firewallName } = req.params;
  const {
    action, // 'ALLOW' | 'DENY'
    direction, // 'INGRESS' | 'EGRESS'
    priority,
    disabled,
    description,
    rules,
    protocol,
    ports,
    sourceRanges,
    destinationRanges,
    sourceTags,
    targetTags,
    targetServiceAccounts,
    enableLogging,
    logMetadata = 'INCLUDE_ALL_METADATA',
  } = req.body || {};

  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    const parseCsvList = (val) => {
      if (val === undefined) return undefined;
      if (Array.isArray(val)) return val.map((x) => String(x).trim()).filter(Boolean);
      if (typeof val === 'string') {
        return val
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean);
      }
      return [];
    };

    const patchBody = {};
    if (priority !== undefined) {
      patchBody.priority = Math.max(0, Math.min(65535, Number(priority)));
    }
    if (disabled !== undefined) {
      patchBody.disabled = Boolean(disabled);
    }
    if (description !== undefined) {
      patchBody.description = String(description);
    }

    // Protocol/port specs if provided
    let protocolSpecs;
    if (Array.isArray(rules) && rules.length > 0) {
      protocolSpecs = rules
        .map((r) => {
          const proto = String(r.IPProtocol || r.protocol || 'tcp')
            .trim()
            .toLowerCase();
          const rawPorts = Array.isArray(r.ports)
            ? r.ports
            : String(r.ports || '')
                .split(',')
                .map((p) => p.trim())
                .filter(Boolean);
          return {
            IPProtocol: proto,
            ...(rawPorts.length > 0 &&
            proto !== 'icmp' &&
            proto !== 'all' &&
            proto !== 'esp' &&
            proto !== 'ah'
              ? { ports: rawPorts }
              : {}),
          };
        })
        .filter((r) => r.IPProtocol);
    } else if (protocol) {
      const proto = String(protocol).trim().toLowerCase();
      const parsedPorts = parseCsvList(ports) || [];
      protocolSpecs = [
        {
          IPProtocol: proto,
          ...(parsedPorts.length > 0 &&
          proto !== 'icmp' &&
          proto !== 'all' &&
          proto !== 'esp' &&
          proto !== 'ah'
            ? { ports: parsedPorts }
            : {}),
        },
      ];
    }

    if (protocolSpecs && protocolSpecs.length > 0) {
      const resolvedAction =
        String(action || 'ALLOW').toUpperCase() === 'DENY' ? 'DENY' : 'ALLOW';
      if (resolvedAction === 'DENY') {
        patchBody.denied = protocolSpecs;
        patchBody.allowed = [];
      } else {
        patchBody.allowed = protocolSpecs;
        patchBody.denied = [];
      }
    }

    const parsedSourceRanges = parseCsvList(sourceRanges);
    const parsedDestRanges = parseCsvList(destinationRanges);
    const parsedSourceTags = parseCsvList(sourceTags);
    const parsedTargetTags = parseCsvList(targetTags);
    const parsedTargetSas = parseCsvList(targetServiceAccounts);

    if (parsedSourceRanges !== undefined && direction !== 'EGRESS') {
      patchBody.sourceRanges = parsedSourceRanges;
    }
    if (parsedDestRanges !== undefined && direction === 'EGRESS') {
      patchBody.destinationRanges = parsedDestRanges;
    }
    if (parsedSourceTags !== undefined) {
      patchBody.sourceTags = parsedSourceTags;
    }
    if (parsedTargetTags !== undefined) {
      patchBody.targetTags = parsedTargetTags;
    }
    if (parsedTargetSas !== undefined && (!parsedTargetTags || parsedTargetTags.length === 0)) {
      patchBody.targetServiceAccounts = parsedTargetSas;
    }
    if (enableLogging !== undefined) {
      patchBody.logConfig = {
        enable: Boolean(enableLogging),
        ...(enableLogging ? { metadata: logMetadata } : {}),
      };
    }

    const op = await gcpFetch(
      `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
        projectId
      )}/global/firewalls/${encodeURIComponent(firewallName)}`,
      token,
      projectId,
      {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: patchBody,
        timeout: 8000,
      }
    );

    res.json({
      ok: true,
      firewallName,
      operation: op,
      operationName: op?.name || null,
      operationUrl: op?.selfLink || null,
      initialStatus: op?.status || 'RUNNING',
      message: `Updated VPC Firewall Rule "${firewallName}" on ${projectId}!`,
    });
  } catch (err) {
    res.status(400).json({
      error:
        err.response?.data?.error?.message ||
        err.message ||
        `Failed to update firewall rule ${firewallName}`,
    });
  }
});

// 10. DELETE /api/project/:projectId/resource -> Explicit user-confirmed deletion of VM, Bucket, Dataset, Cloud Run Service, VPC Network, or Firewall Rule
app.delete('/api/project/:projectId/resource', async (req, res) => {
  const { projectId } = req.params;
  const {
    type,
    resourceType,
    name,
    region = 'us-east1-b',
    confirmName,
  } = req.body || {};
  const resolvedType = type || resourceType;

  if (!name || (confirmName && name !== confirmName)) {
    return res.status(400).json({
      error: 'Confirmation name does not match resource name.',
    });
  }

  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    if (resolvedType === 'Compute Engine VM' || resolvedType === 'COMPUTE_VM') {
      const zone = region || 'us-east1-b';
      const op = await gcpFetch(
        `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
          projectId
        )}/zones/${encodeURIComponent(zone)}/instances/${encodeURIComponent(
          name
        )}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 8000 }
      );
      return res.json({
        ok: true,
        operation: op,
        operationName: op?.name || null,
        operationUrl: op?.selfLink || null,
        message: `Dispatched live Compute Engine DELETE operation for VM "${name}" in ${zone}.`,
      });
    }

    if (
      resolvedType === 'VPC Network' ||
      resolvedType === 'VPC_NETWORK'
    ) {
      const op = await gcpFetch(
        `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
          projectId
        )}/global/networks/${encodeURIComponent(name)}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 8000 }
      );
      return res.json({
        ok: true,
        operation: op,
        operationName: op?.name || null,
        operationUrl: op?.selfLink || null,
        message: `Dispatched live DELETE operation for VPC Network "${name}" in ${projectId}.`,
      });
    }

    if (
      resolvedType === 'VPC Firewall Rule' ||
      resolvedType === 'VPC_FIREWALL'
    ) {
      const op = await gcpFetch(
        `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
          projectId
        )}/global/firewalls/${encodeURIComponent(name)}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 8000 }
      );
      return res.json({
        ok: true,
        operation: op,
        operationName: op?.name || null,
        operationUrl: op?.selfLink || null,
        message: `Dispatched live DELETE operation for VPC Firewall Rule "${name}" in ${projectId}.`,
      });
    }

    if (
      resolvedType === 'Cloud Storage Bucket' ||
      resolvedType === 'Cloud Storage' ||
      resolvedType === 'GCS_BUCKET'
    ) {
      await gcpFetch(
        `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
          name
        )}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 6000 }
      );
      return res.json({
        ok: true,
        message: `Deleted Cloud Storage bucket gs://${name} from ${projectId}.`,
      });
    }

    if (
      resolvedType === 'BigQuery Dataset' ||
      resolvedType === 'BIGQUERY_DATASET'
    ) {
      await gcpFetch(
        `https://bigquery.googleapis.com/bigquery/v2/projects/${encodeURIComponent(
          projectId
        )}/datasets/${encodeURIComponent(name)}?deleteContents=true`,
        token,
        projectId,
        { method: 'DELETE', timeout: 6000 }
      );
      return res.json({
        ok: true,
        message: `Deleted BigQuery dataset ${projectId}.${name}.`,
      });
    }

    if (
      resolvedType === 'Cloud Run Service' ||
      resolvedType === 'Cloud Run' ||
      resolvedType === 'CLOUD_RUN'
    ) {
      const loc = region || 'us-east1';
      await gcpFetch(
        `https://run.googleapis.com/v2/projects/${encodeURIComponent(
          projectId
        )}/locations/${encodeURIComponent(loc)}/services/${encodeURIComponent(
          name
        )}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 6000 }
      );
      return res.json({
        ok: true,
        message: `Deleted Cloud Run service ${name} in ${loc}.`,
      });
    }

    if (
      resolvedType === 'Enabled GCP Service API' ||
      resolvedType === 'GCP_API'
    ) {
      const serviceName = (req.body?.serviceName || name).trim().toLowerCase();
      await gcpFetch(
        `https://serviceusage.googleapis.com/v1/projects/${encodeURIComponent(
          projectId
        )}/services/${encodeURIComponent(serviceName)}:disable`,
        token,
        projectId,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: { disableDependentServices: true },
          timeout: 12000,
        }
      );
      if (!projectDisabledOverrideMap.has(projectId)) {
        projectDisabledOverrideMap.set(projectId, new Set());
      }
      projectDisabledOverrideMap.get(projectId).add(serviceName);
      const cached = projectEnabledApisCache.get(projectId) || [];
      projectEnabledApisCache.set(
        projectId,
        cached.filter((a) => a.name !== serviceName)
      );
      return res.json({
        ok: true,
        message: `Emergency Kill-Switch: Disabled Google Cloud API "${serviceName}" on project ${projectId}.`,
      });
    }

    if (
      resolvedType === 'Secret Manager Secret' ||
      resolvedType === 'SECRET_MANAGER'
    ) {
      const shortName = String(name).split('/').pop();
      await gcpFetch(
        `https://secretmanager.googleapis.com/v1/projects/${encodeURIComponent(
          projectId
        )}/secrets/${encodeURIComponent(shortName)}`,
        token,
        projectId,
        { method: 'DELETE', timeout: 8000 }
      );
      return res.json({
        ok: true,
        message: `Deleted Secret Manager secret "${shortName}" from project ${projectId}.`,
      });
    }

    res
      .status(400)
      .json({ error: `Deletion not supported for type: ${resolvedType}` });
  } catch (err) {
    res.status(400).json({
      error: err.response?.data?.error?.message || err.message,
    });
  }
});

// 10a. GET /api/project/:projectId/apis -> Fast dedicated endpoint for enabled Google Cloud APIs
app.get('/api/project/:projectId/apis', async (req, res) => {
  const { projectId } = req.params;
  const forceRefresh = req.query.refresh === 'true';
  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    if (!forceRefresh && projectEnabledApisCache.has(projectId)) {
      const cached = projectEnabledApisCache.get(projectId);
      if (cached && cached.length > 0) {
        return res.json({
          projectId,
          count: cached.length,
          enabledApis: cached,
        });
      }
    }

    const rawServices = await fetchProjectEnabledApis(projectId, token);
    const enabledApis = normalizeAndSortEnabledApis(rawServices, [], projectId);
    res.json({
      projectId,
      count: enabledApis.length,
      enabledApis,
    });
  } catch (err) {
    const fallback = projectEnabledApisCache.get(projectId) || [];
    res.json({
      projectId,
      count: fallback.length,
      enabledApis: fallback,
      warning: err.response?.data?.error?.message || err.message,
    });
  }
});

// 10b. POST /api/project/:projectId/apis/toggle -> Emergency Mobile API Kill-Switch (Disable or Enable any GCP Service API)
app.post('/api/project/:projectId/apis/toggle', async (req, res) => {
  const { projectId } = req.params;
  const {
    serviceName,
    action = 'DISABLE',
    disableDependentServices = true,
  } = req.body || {};

  if (!serviceName) {
    return res
      .status(400)
      .json({ error: 'serviceName is required (e.g. compute.googleapis.com).' });
  }

  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    const cleanService = serviceName.trim().toLowerCase();
    const isDisable = action.toUpperCase() === 'DISABLE';
    const url = `https://serviceusage.googleapis.com/v1/projects/${encodeURIComponent(
      projectId
    )}/services/${encodeURIComponent(cleanService)}:${
      isDisable ? 'disable' : 'enable'
    }`;

    const op = await gcpFetch(url, token, projectId, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: isDisable ? { disableDependentServices } : {},
      timeout: 12000,
    });

    if (!projectDisabledOverrideMap.has(projectId)) {
      projectDisabledOverrideMap.set(projectId, new Set());
    }
    const disabledSet = projectDisabledOverrideMap.get(projectId);
    const cached = projectEnabledApisCache.get(projectId) || [];

    if (isDisable) {
      disabledSet.add(cleanService);
      projectEnabledApisCache.set(
        projectId,
        cached.filter((a) => a.name !== cleanService)
      );
    } else {
      disabledSet.delete(cleanService);
      if (!cached.some((a) => a.name === cleanService)) {
        const updated = [
          {
            name: cleanService,
            title: FRIENDLY_API_TITLES[cleanService] || cleanService,
            state: 'ENABLED',
            isPriority: PRIORITY_API_ORDER.includes(cleanService),
          },
          ...cached,
        ];
        projectEnabledApisCache.set(projectId, updated);
      }
    }

    res.json({
      ok: true,
      serviceName: cleanService,
      action: isDisable ? 'DISABLED' : 'ENABLED',
      enabledApis: projectEnabledApisCache.get(projectId) || [],
      operation: op,
      message: isDisable
        ? `Emergency Kill-Switch: Dispatched live DISABLE for ${cleanService} on ${projectId}.`
        : `Dispatched live ENABLE for ${cleanService} on ${projectId}.`,
    });
  } catch (err) {
    res.status(400).json({
      error:
        err.response?.data?.error?.message ||
        err.message ||
        `Failed to ${action} API ${serviceName}`,
    });
  }
});

// Track previously linked billing account per project so user can re-link in 1 tap after an emergency kill
const projectPreviousBillingMap = new Map();

async function ensureCloudBillingApiEnabled(projectId, token) {
  try {
    await gcpFetch(
      `https://serviceusage.googleapis.com/v1/projects/${encodeURIComponent(
        projectId
      )}/services/cloudbilling.googleapis.com:enable`,
      token,
      projectId,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: {},
        timeout: 10000,
      }
    );
  } catch {
    // ignore if already enabled
  }
}

async function fetchProjectBillingStatus(projectId, token) {
  const infoUrl = `https://cloudbilling.googleapis.com/v1/projects/${encodeURIComponent(
    projectId
  )}/billingInfo`;
  const accountsUrl = `https://cloudbilling.googleapis.com/v1/billingAccounts`;

  let billingInfo;
  let billingAccounts = [];

  try {
    const [infoRes, acctsRes] = await Promise.allSettled([
      gcpFetch(infoUrl, token, projectId, { timeout: 8000 }),
      gcpFetch(accountsUrl, token, projectId, { timeout: 8000 }),
    ]);

    if (infoRes.status === 'rejected') {
      const errMsg =
        infoRes.reason?.response?.data?.error?.message ||
        infoRes.reason?.message ||
        '';
      if (
        errMsg.includes('Cloud Billing API has not been used') ||
        errMsg.includes('cloudbilling.googleapis.com')
      ) {
        await ensureCloudBillingApiEnabled(projectId, token);
        billingInfo = await gcpFetch(infoUrl, token, projectId, {
          timeout: 8000,
        });
      } else {
        throw infoRes.reason;
      }
    } else {
      billingInfo = infoRes.value;
    }

    if (acctsRes.status === 'fulfilled') {
      billingAccounts = acctsRes.value?.billingAccounts || [];
    } else {
      try {
        const retryAccts = await gcpFetch(accountsUrl, token, projectId, {
          timeout: 8000,
        });
        billingAccounts = retryAccts?.billingAccounts || [];
      } catch {
        billingAccounts = [];
      }
    }
  } catch (err) {
    // Fallback without x-goog-user-project quota header if needed
    billingInfo = await gcpFetch(infoUrl, token, null, { timeout: 8000 });
    try {
      const acctsData = await gcpFetch(accountsUrl, token, null, {
        timeout: 8000,
      });
      billingAccounts = acctsData?.billingAccounts || [];
    } catch {
      billingAccounts = [];
    }
  }

  const billingEnabled = Boolean(billingInfo?.billingEnabled);
  const billingAccountName = billingInfo?.billingAccountName || '';

  if (billingEnabled && billingAccountName) {
    projectPreviousBillingMap.set(projectId, billingAccountName);
  }

  const matchedAccount = billingAccounts.find(
    (a) => a.name === billingAccountName
  );
  const openBillingAccounts = billingAccounts
    .filter((a) => a.open)
    .map((a) => ({
      name: a.name,
      displayName: a.displayName || a.name,
      currencyCode: a.currencyCode || 'USD',
      open: true,
    }));

  const previousBillingAccountName =
    projectPreviousBillingMap.get(projectId) ||
    openBillingAccounts[0]?.name ||
    '';
  const previousMatched = billingAccounts.find(
    (a) => a.name === previousBillingAccountName
  );

  return {
    projectId,
    billingEnabled,
    billingAccountName,
    billingAccountDisplayName:
      matchedAccount?.displayName ||
      (billingAccountName
        ? billingAccountName.replace('billingAccounts/', '')
        : 'No Billing Account Linked ($0 Spend Lockdown)'),
    currencyCode: matchedAccount?.currencyCode || 'USD',
    previousBillingAccountName,
    previousBillingAccountDisplayName:
      previousMatched?.displayName || previousBillingAccountName,
    openBillingAccounts,
    totalBillingAccountsCount: billingAccounts.length,
  };
}

// 10c. GET /api/project/:projectId/billing -> Live Cloud Billing Account status & linked account details
app.get('/api/project/:projectId/billing', async (req, res) => {
  const { projectId } = req.params;
  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    const status = await fetchProjectBillingStatus(projectId, token);
    res.json(status);
  } catch (err) {
    res.status(400).json({
      error:
        err.response?.data?.error?.message ||
        err.message ||
        `Failed to fetch Cloud Billing status for ${projectId}`,
    });
  }
});

// 10d. POST /api/project/:projectId/billing/kill-switch -> Ultimate Project Emergency Kill-Switch (Unlink or Re-Link Billing Account)
app.post('/api/project/:projectId/billing/kill-switch', async (req, res) => {
  const { projectId } = req.params;
  const {
    action = 'DISABLE',
    billingAccountName = '',
    stopAllVms = false,
  } = req.body || {};

  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    const isDisable = action.toUpperCase() === 'DISABLE';
    const infoUrl = `https://cloudbilling.googleapis.com/v1/projects/${encodeURIComponent(
      projectId
    )}/billingInfo`;

    // Record current billing account before unlinking so user can re-link later
    if (isDisable) {
      try {
        const current = await gcpFetch(infoUrl, token, projectId, {
          timeout: 6000,
        });
        if (current?.billingAccountName) {
          projectPreviousBillingMap.set(projectId, current.billingAccountName);
        }
      } catch {
        // ignore
      }
    }

    const targetAccountToLink = isDisable
      ? ''
      : (
          billingAccountName ||
          projectPreviousBillingMap.get(projectId) ||
          ''
        ).trim();

    if (!isDisable && !targetAccountToLink) {
      return res.status(400).json({
        error:
          'Please select a valid Billing Account (e.g. billingAccounts/01XXXX-XXXXXX-XXXXXX) to re-link.',
      });
    }

    const updatedInfo = await gcpFetch(infoUrl, token, projectId, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: {
        billingAccountName: targetAccountToLink,
      },
      timeout: 12000,
    });

    const stoppedVms = [];
    if (isDisable && stopAllVms) {
      try {
        const vmsData = await gcpFetch(
          `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
            projectId
          )}/aggregated/instances?maxResults=50&returnPartialSuccess=true`,
          token,
          projectId,
          { timeout: 6000 }
        );
        const runningVms = Object.entries(vmsData.items || {}).flatMap(
          ([zoneKey, val]) =>
            (val.instances || [])
              .filter((inst) => inst.status === 'RUNNING')
              .map((inst) => ({
                name: inst.name,
                zone: zoneKey.replace('zones/', ''),
              }))
        );
        await Promise.allSettled(
          runningVms.map(async (vm) => {
            await gcpFetch(
              `https://compute.googleapis.com/compute/v1/projects/${encodeURIComponent(
                projectId
              )}/zones/${encodeURIComponent(
                vm.zone
              )}/instances/${encodeURIComponent(vm.name)}/stop`,
              token,
              projectId,
              { method: 'POST', timeout: 8000 }
            );
            stoppedVms.push(`${vm.name} (${vm.zone})`);
          })
        );
      } catch {
        // ignore VM stop errors if compute API is disabled
      }
    }

    const freshStatus = await fetchProjectBillingStatus(projectId, token);

    res.json({
      ok: true,
      action: isDisable ? 'BILLING_DISABLED' : 'BILLING_ENABLED',
      updatedInfo,
      stoppedVms,
      billing: freshStatus,
      message: isDisable
        ? `EMERGENCY PROJECT KILL-SWITCH ACTIVATED: Unlinked Billing Account from "${projectId}". Project spending is now $0.00!${
            stoppedVms.length
              ? ` Also halted ${stoppedVms.length} running VM(s): ${stoppedVms.join(', ')}.`
              : ''
          }`
        : `Restored & re-linked Billing Account (${freshStatus.billingAccountDisplayName} — ${freshStatus.billingAccountName}) on project "${projectId}".`,
    });
  } catch (err) {
    res.status(400).json({
      error:
        err.response?.data?.error?.message ||
        err.message ||
        `Failed to update Cloud Billing on ${projectId}`,
    });
  }
});

// ============================================================================
// CLOUD RUN COMMAND CENTER ENDPOINTS (SERVICES, REVISIONS, SCALING, IAM, TRAFFIC)
// ============================================================================

// 10e. GET /api/project/:projectId/cloudrun -> Full Cloud Run Services, Revisions, Scaling & IAM Policy
app.get('/api/project/:projectId/cloudrun', async (req, res) => {
  const { projectId } = req.params;
  try {
    const { token } = await resolveRequestAuth(req);
    if (!token) return res.status(401).json({ error: 'Not authenticated.' });

    let rawServices = [];
    let runApiEnabled = true;
    let runApiMessage = '';

    try {
      const data = await gcpFetch(
        `https://run.googleapis.com/v2/projects/${encodeURIComponent(
          projectId
        )}/locations/-/services`,
        token,
        projectId,
        { timeout: 8000 }
      );
      rawServices = data.services || [];
    } catch (err) {
      runApiEnabled = false;
      runApiMessage = err.response?.data?.error?.message || err.message;
    }

    // Enrich each service with IAM policy (public/private) and recent revisions
    const enrichedServices = await Promise.all(
      rawServices.map(async (srv) => {
        const shortName = srv.name?.split('/').pop();
        const region = srv.name?.split('/')[3] || 'us-east1';
        let allowUnauthenticated = false;
        let iapServiceAgentBound = false;
        let iapServiceAgentEmail = '';
        let invokerMembers = [];
        let revisions = [];

        const [iamRes, revRes] = await Promise.allSettled([
          gcpFetch(
            `https://run.googleapis.com/v2/projects/${encodeURIComponent(
              projectId
            )}/locations/${encodeURIComponent(
              region
            )}/services/${encodeURIComponent(shortName)}:getIamPolicy`,
            token,
            projectId,
            { timeout: 4000 }
          ),
          gcpFetch(
            `https://run.googleapis.com/v2/projects/${encodeURIComponent(
              projectId
            )}/locations/${encodeURIComponent(
              region
            )}/services/${encodeURIComponent(shortName)}/revisions?pageSize=10`,
            token,
            projectId,
            { timeout: 4000 }
          ),
        ]);

        if (iamRes.status === 'fulfilled') {
          const bindings = iamRes.value?.bindings || [];
          const invokerB = bindings.find((b) => b.role === 'roles/run.invoker');
          invokerMembers = invokerB?.members || [];
          allowUnauthenticated = invokerMembers.includes('allUsers');
          const iapSaMember = invokerMembers.find((m) =>
            String(m).includes('@gcp-sa-iap.')
          );
          if (iapSaMember) {
            iapServiceAgentBound = true;
            iapServiceAgentEmail = String(iapSaMember).replace(
              /^serviceAccount:/,
              ''
            );
          }
        }

        if (revRes.status === 'fulfilled') {
          revisions = (revRes.value?.revisions || []).map((r) => {
            const c = r.containers?.[0] || {};
            const lim = c.resources?.limits || {};
            const readyCond =
              r.terminalCondition ||
              (r.conditions || []).find((cd) => cd.type === 'Ready') ||
              {};
            const condState = String(readyCond.state || '');
            const healthStatus =
              condState === 'CONDITION_FAILED'
                ? 'CRASHED'
                : condState === 'CONDITION_RECONCILING' || r.reconciling
                ? 'RECONCILING'
                : 'HEALTHY';
            const failureReason =
              readyCond.revisionReason ||
              readyCond.executionReason ||
              readyCond.reason ||
              '';
            const failureMessage = readyCond.message || '';
            const rawEnv = Array.isArray(c.env) ? c.env : [];
            return {
              name: r.name,
              shortName: r.name?.split('/').pop() || '',
              createTime: r.createTime || new Date().toISOString(),
              containerImage: c.image || '',
              containerPort: Number(c.ports?.[0]?.containerPort || 8080),
              cpu: lim.cpu || '1',
              memory: lim.memory || '512Mi',
              cpuIdle: c.resources?.cpuIdle !== false,
              startupCpuBoost: Boolean(c.resources?.startupCpuBoost),
              minInstances: Number(r.scaling?.minInstanceCount || 0),
              maxInstances: Number(r.scaling?.maxInstanceCount || 10),
              concurrency: Number(r.maxInstanceRequestConcurrency || 80),
              serviceAccount: r.serviceAccount || '',
              executionEnvironment:
                r.executionEnvironment || 'EXECUTION_ENVIRONMENT_GEN2',
              healthStatus,
              failureReason,
              failureMessage,
              logUri: r.logUri || '',
              envVarKeys: rawEnv
                .filter((e) => e && e.name && !e.valueSource?.secretKeyRef)
                .map((e) => e.name),
              secretRefs: rawEnv
                .filter((e) => e && e.name && e.valueSource?.secretKeyRef)
                .map((e) => ({
                  name: e.name,
                  secretName: String(
                    e.valueSource.secretKeyRef.secret || ''
                  )
                    .split('/')
                    .pop(),
                  version: e.valueSource.secretKeyRef.version || 'latest',
                })),
            };
          });
        }

        return formatCloudRunService(srv, projectId, {
          allowUnauthenticated,
          iapEnabled:
            srv.iapEnabled === true ||
            srv.annotations?.['run.googleapis.com/iap-enabled'] === 'true' ||
            srv.metadata?.annotations?.['run.googleapis.com/iap-enabled'] ===
              'true' ||
            iapServiceAgentBound,
          iapServiceAgentBound,
          iapServiceAgentEmail,
          invokerMembers,
          revisions,
        });
      })
    );

    res.json({
      projectId,
      runApiEnabled,
      runApiMessage,
      count: enrichedServices.length,
      services: enrichedServices,
    });
  } catch (err) {
    res.status(500).json({
      error: err.response?.data?.error?.message || err.message,
    });
  }
});

// 10f. PATCH /api/project/:projectId/cloudrun/:region/:serviceName -> Live Update CPU, Memory, GPU, Billing Mode, Scaling, Image, Port, Ingress & Env Vars
app.patch(
  '/api/project/:projectId/cloudrun/:region/:serviceName',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const config = req.body || {};

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      const existing = await gcpFetch(serviceUrl, token, projectId, {
        timeout: 8000,
      });

      const currentContainer = existing.template?.containers?.[0] || {};
      const currentLimits = currentContainer.resources?.limits || {};
      const currentScaling = existing.template?.scaling || {};

      const containerImage =
        config.containerImage ||
        currentContainer.image ||
        'us-docker.pkg.dev/cloudrun/container/hello';
      const containerPort = Number(
        config.containerPort ??
          currentContainer.ports?.[0]?.containerPort ??
          8080
      );

      // 2026 GPU Accelerator configuration
      const currentGpuCount = Number(currentLimits['nvidia.com/gpu'] || 0);
      const gpuCount = Math.max(
        0,
        Number(
          config.gpuCount !== undefined ? config.gpuCount : currentGpuCount
        )
      );
      const gpuType =
        config.gpuType ||
        existing.template?.nodeSelector?.accelerator ||
        'nvidia-l4';
      const gpuZonalRedundancy =
        config.gpuZonalRedundancy !== undefined
          ? Boolean(config.gpuZonalRedundancy)
          : existing.template?.gpuZonalRedundancyDisabled === undefined
          ? false
          : !existing.template.gpuZonalRedundancyDisabled;

      let cpu = String(config.cpu || currentLimits.cpu || '1');
      let memory = String(config.memory || currentLimits.memory || '512Mi');

      // Enforce Cloud Run GPU minimums (at least 4 vCPU & 16Gi RAM when GPU is attached)
      if (gpuCount > 0) {
        if (Number(cpu) < 4) cpu = '4';
        const memMatch = memory.match(/^(\d+)(Mi|Gi)$/);
        const memGi = memMatch
          ? memMatch[2] === 'Gi'
            ? Number(memMatch[1])
            : Number(memMatch[1]) / 1024
          : 0;
        if (memGi < 16) memory = '16Gi';
      }

      // 2026 Billing Mode: Request-based (cpuIdle: true) vs Instance-based (cpuIdle: false)
      const billingMode =
        gpuCount > 0
          ? 'INSTANCE_BASED'
          : config.billingMode ||
            (config.cpuIdle !== undefined
              ? config.cpuIdle
                ? 'REQUEST_BASED'
                : 'INSTANCE_BASED'
              : currentContainer.resources?.cpuIdle !== false
              ? 'REQUEST_BASED'
              : 'INSTANCE_BASED');
      const cpuIdle = billingMode === 'REQUEST_BASED' && gpuCount === 0;

      const startupCpuBoost =
        config.startupCpuBoost !== undefined
          ? Boolean(config.startupCpuBoost)
          : Boolean(currentContainer.resources?.startupCpuBoost);
      const minInstances = Math.max(
        0,
        Number(config.minInstances ?? currentScaling.minInstanceCount ?? 0)
      );
      const maxInstances = Math.max(
        minInstances || 1,
        Number(config.maxInstances ?? currentScaling.maxInstanceCount ?? 10)
      );
      const concurrency = Math.max(
        1,
        Number(
          config.concurrency ??
            existing.template?.maxInstanceRequestConcurrency ??
            80
        )
      );
      const timeoutSeconds = Math.max(
        10,
        Number(
          config.timeoutSeconds ??
            (parseInt(
              String(existing.template?.timeout || '300s').replace('s', ''),
              10
            ) ||
              300)
        )
      );
      const ingress =
        config.ingress || existing.ingress || 'INGRESS_TRAFFIC_ALL';

      // 2026 Direct VPC Egress + Storage Volume Mounts (GCS FUSE / In-Memory RAM / NFS Filestore)
      const {
        vpcAccess,
        vpcSummary,
        volumes,
        volumeMounts,
        storageSummary,
        requiresGen2,
      } = buildCloudRunVpcAndVolumes(config, existing.template || {});

      const executionEnvironment =
        gpuCount > 0 || requiresGen2
          ? 'EXECUTION_ENVIRONMENT_GEN2'
          : config.executionEnvironment ||
            existing.template?.executionEnvironment ||
            'EXECUTION_ENVIRONMENT_GEN2';

      const existingSecretEnvs = (currentContainer.env || []).filter(
        (e) => e && e.name && e.valueSource?.secretKeyRef
      );
      const parsedPlaintextEnvs =
        config.envVars !== undefined
          ? parseEnvVarsInput(config.envVars)
          : (currentContainer.env || []).filter(
              (e) => e && e.name && !e.valueSource?.secretKeyRef
            );
      const plaintextNames = new Set(parsedPlaintextEnvs.map((e) => e.name));
      const envList = [
        ...existingSecretEnvs.filter((e) => !plaintextNames.has(e.name)),
        ...parsedPlaintextEnvs,
      ];

      if (
        executionEnvironment === 'EXECUTION_ENVIRONMENT_GEN2' &&
        (memory === '128Mi' || memory === '256Mi')
      ) {
        memory = '512Mi';
      }

      const resourceLimits = { cpu, memory };
      if (gpuCount > 0) {
        resourceLimits['nvidia.com/gpu'] = String(gpuCount);
      }

      const nextContainer = {
        ...currentContainer,
        image: containerImage,
        ports: [{ name: 'http1', containerPort }],
        resources: {
          limits: resourceLimits,
          cpuIdle,
          startupCpuBoost,
        },
        env: envList,
      };
      if (volumeMounts.length > 0) {
        nextContainer.volumeMounts = volumeMounts;
      } else {
        delete nextContainer.volumeMounts;
      }

      const runtimeServiceAccount = await resolveRuntimeServiceAccount(
        projectId,
        token,
        config.serviceAccount ||
          config.serviceAccountEmail ||
          existing.template?.serviceAccount
      );

      const templateObj = {
        ...(runtimeServiceAccount
          ? { serviceAccount: runtimeServiceAccount }
          : {}),
        scaling: {
          minInstanceCount: minInstances,
          maxInstanceCount: maxInstances,
        },
        maxInstanceRequestConcurrency: concurrency,
        timeout: `${timeoutSeconds}s`,
        executionEnvironment,
        ...(vpcAccess ? { vpcAccess } : {}),
        ...(volumes.length > 0 ? { volumes } : {}),
        containers: [nextContainer],
      };

      if (gpuCount > 0) {
        templateObj.nodeSelector = {
          accelerator: gpuType,
        };
        templateObj.gpuZonalRedundancyDisabled = !gpuZonalRedundancy;
      }

      const patchBody = {
        ingress,
        template: templateObj,
      };

      const op = await gcpFetch(serviceUrl, token, projectId, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: patchBody,
        timeout: 12000,
      });

      const gpuSummary = gpuCount > 0 ? `, ${gpuCount}x ${gpuType} GPU` : '';
      const billingSummary = cpuIdle
        ? 'Request-based billing'
        : 'Instance-based billing';
      const vpcBadge = vpcSummary ? `, ${vpcSummary}` : '';
      const storageBadge = storageSummary ? `, ${storageSummary}` : '';

      res.json({
        ok: true,
        operation: op,
        message: `Deployed new Cloud Run revision for "${serviceName}" (${cpu} vCPU, ${memory}${gpuSummary}, ${billingSummary}${vpcBadge}${storageBadge}, scale ${minInstances}→${maxInstances})!`,
      });
    } catch (err) {
      res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to update Cloud Run service ${serviceName}`,
      });
    }
  }
);

// 10g. POST /api/project/:projectId/cloudrun/:region/:serviceName/iam -> Toggle Public Unauthenticated (allUsers) vs Private IAM Access
app.post(
  '/api/project/:projectId/cloudrun/:region/:serviceName/iam',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const { allowUnauthenticated = true } = req.body || {};

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const iamBaseUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      let existingBindings = [];
      try {
        const currentPolicy = await gcpFetch(
          `${iamBaseUrl}:getIamPolicy`,
          token,
          projectId,
          { timeout: 6000 }
        );
        existingBindings = currentPolicy?.bindings || [];
      } catch {
        existingBindings = [];
      }

      // Filter out allUsers from roles/run.invoker
      const cleanedBindings = existingBindings
        .map((b) => {
          if (b.role !== 'roles/run.invoker') return b;
          return {
            ...b,
            members: (b.members || []).filter((m) => m !== 'allUsers'),
          };
        })
        .filter((b) => (b.members || []).length > 0);

      if (allowUnauthenticated) {
        const invokerBinding = cleanedBindings.find(
          (b) => b.role === 'roles/run.invoker'
        );
        if (invokerBinding) {
          invokerBinding.members.push('allUsers');
        } else {
          cleanedBindings.push({
            role: 'roles/run.invoker',
            members: ['allUsers'],
          });
        }
      }

      const [updatedPolicy] = await Promise.all([
        gcpFetch(`${iamBaseUrl}:setIamPolicy`, token, projectId, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: {
            policy: {
              bindings: cleanedBindings,
            },
          },
          timeout: 8000,
        }).catch(() => null),
        gcpFetch(
          `${iamBaseUrl}?updateMask=invokerIamDisabled`,
          token,
          projectId,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: {
              invokerIamDisabled: Boolean(allowUnauthenticated),
            },
            timeout: 8000,
          }
        ).catch(() => null),
      ]);

      res.json({
        ok: true,
        allowUnauthenticated: Boolean(allowUnauthenticated),
        policy: updatedPolicy,
        message: allowUnauthenticated
          ? `Granted Public HTTPS Invoker (allUsers / invokerIamDisabled=true) on Cloud Run service "${serviceName}".`
          : `Locked down "${serviceName}" to Private IAM Authenticated invocations only.`,
      });
    } catch (err) {
      res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to update IAM policy for ${serviceName}`,
      });
    }
  }
);

// 10g-2. GET & POST /api/project/:projectId/cloudrun/:region/:serviceName/iap -> App Engine-Style 1-Click Cloud Run IAP (Zero-LB Direct IAP + IAP Service Agent + HTTPS Resource Accessors)
app.get(
  '/api/project/:projectId/cloudrun/:region/:serviceName/iap',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    try {
      const { token, account } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      const [projRes, srvRes, runIamRes] = await Promise.allSettled([
        gcpFetch(
          `https://cloudresourcemanager.googleapis.com/v1/projects/${encodeURIComponent(
            projectId
          )}`,
          token,
          projectId,
          { timeout: 6000 }
        ),
        gcpFetch(serviceUrl, token, projectId, { timeout: 6000 }),
        gcpFetch(`${serviceUrl}:getIamPolicy`, token, projectId, {
          timeout: 6000,
        }),
      ]);

      const projectNumber =
        projRes.status === 'fulfilled'
          ? String(projRes.value?.projectNumber || '')
          : '';
      const parentType =
        projRes.status === 'fulfilled'
          ? String(projRes.value?.parent?.type || '')
          : '';
      const isOrglessProject = parentType !== 'organization';
      const srv = srvRes.status === 'fulfilled' ? srvRes.value || {} : {};
      const runBindings =
        runIamRes.status === 'fulfilled'
          ? runIamRes.value?.bindings || []
          : [];
      const invokerMembers =
        runBindings.find((b) => b.role === 'roles/run.invoker')?.members || [];

      const iapServiceAgent = projectNumber
        ? `service-${projectNumber}@gcp-sa-iap.iam.gserviceaccount.com`
        : 'service-<PROJECT_NUMBER>@gcp-sa-iap.iam.gserviceaccount.com';
      const iapServiceAgentHasInvoker = invokerMembers.some(
        (m) =>
          m === `serviceAccount:${iapServiceAgent}` ||
          String(m).includes('@gcp-sa-iap.')
      );
      const allowUnauthenticated =
        invokerMembers.includes('allUsers') || srv.invokerIamDisabled === true;
      const annotationEnabled =
        srv.iapEnabled === true ||
        srv.annotations?.['run.googleapis.com/iap-enabled'] === 'true' ||
        srv.metadata?.annotations?.['run.googleapis.com/iap-enabled'] ===
          'true';

      let iapAccessors = [];
      let oauthClientId = '';
      let oauthClientConfigured = false;
      if (projectNumber) {
        try {
          const iapSettingsRes = await gcpFetch(
            `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
              projectNumber
            )}/iap_web:iapSettings`,
            token,
            projectId,
            { timeout: 5000 }
          ).catch(() => null);
          const oauthCfg =
            iapSettingsRes?.accessSettings?.oauthSettings || {};
          if (oauthCfg.clientId) {
            oauthClientId = String(oauthCfg.clientId);
            oauthClientConfigured = Boolean(
              oauthCfg.clientId && oauthCfg.clientSecretSha256
            );
          }
        } catch {
          // ignore
        }

        try {
          const iapPolicy = await gcpFetch(
            `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
              projectNumber
            )}/iap_web/cloud_run-${encodeURIComponent(
              region
            )}/services/${encodeURIComponent(serviceName)}:getIamPolicy`,
            token,
            projectId,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: {},
              timeout: 5000,
            }
          );
          const accBinding = (iapPolicy?.bindings || []).find(
            (b) => b.role === 'roles/iap.httpsResourceAccessor'
          );
          iapAccessors = accBinding?.members || [];
        } catch {
          // Fallback to project-wide iap_web policy
          try {
            const projIapPolicy = await gcpFetch(
              `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
                projectNumber
              )}/iap_web:getIamPolicy`,
              token,
              projectId,
              {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: {},
                timeout: 5000,
              }
            );
            const accBinding = (projIapPolicy?.bindings || []).find(
              (b) => b.role === 'roles/iap.httpsResourceAccessor'
            );
            iapAccessors = accBinding?.members || [];
          } catch {
            iapAccessors = [];
          }
        }
      }

      const defaultUserPrincipal = account ? `user:${account}` : '';
      const effectiveAccessors =
        iapAccessors.length > 0
          ? iapAccessors
          : defaultUserPrincipal
          ? [defaultUserPrincipal]
          : [];

      res.json({
        ok: true,
        projectId,
        projectNumber,
        isOrglessProject,
        oauthClientConfigured,
        oauthClientId,
        requiredRedirectUri: `https://iap.googleapis.com/v1/oauth/clientIds/${
          oauthClientId || '<YOUR_OAUTH_CLIENT_ID>'
        }:handleRedirect`,
        region,
        serviceName,
        iapEnabled: Boolean(annotationEnabled || iapServiceAgentHasInvoker),
        annotationEnabled,
        iapServiceAgent,
        iapServiceAgentHasInvoker,
        allowUnauthenticated,
        iapAccessors,
        suggestedAccessors: effectiveAccessors,
        invokerMembers,
        activeAccount: account || '',
        cliCommands: {
          enableDirectIap: `gcloud beta run services update ${serviceName} --region=${region} --project=${projectId} --iap --no-allow-unauthenticated`,
          disableDirectIap: `gcloud beta run services update ${serviceName} --region=${region} --project=${projectId} --no-iap`,
          grantAccessor: `gcloud iap web add-iam-policy-binding --resource-type=cloud-run --service=${serviceName} --region=${region} --project=${projectId} --member="${
            effectiveAccessors[0] || 'user:you@example.com'
          }" --role="roles/iap.httpsResourceAccessor"`,
        },
      });
    } catch (err) {
      res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to inspect Cloud IAP status for ${serviceName}`,
      });
    }
  }
);

app.post(
  '/api/project/:projectId/cloudrun/:region/:serviceName/iap',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const {
      enabled = true,
      accessors = [],
      oauthClientId = '',
      oauthClientSecret = '',
    } = req.body || {};
    const targetEnabled = Boolean(enabled);

    try {
      const { token, account } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const steps = [];
      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      // Step 1: Resolve projectNumber & ensure iap.googleapis.com + IAP Service Agent exist
      let projectNumber = '';
      let isOrglessProject = true;
      let oauthClientConfigured = Boolean(
        String(oauthClientId || '').trim() &&
          String(oauthClientSecret || '').trim()
      );
      try {
        const projData = await gcpFetch(
          `https://cloudresourcemanager.googleapis.com/v1/projects/${encodeURIComponent(
            projectId
          )}`,
          token,
          projectId,
          { timeout: 6000 }
        );
        projectNumber = String(projData?.projectNumber || '');
        isOrglessProject =
          String(projData?.parent?.type || '') !== 'organization';
      } catch {
        projectNumber = '';
      }

      const iapServiceAgent = projectNumber
        ? `service-${projectNumber}@gcp-sa-iap.iam.gserviceaccount.com`
        : '';

      if (targetEnabled) {
        try {
          await gcpFetch(
            `https://serviceusage.googleapis.com/v1/projects/${encodeURIComponent(
              projectId
            )}/services/iap.googleapis.com:enable`,
            token,
            projectId,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: {},
              timeout: 8000,
            }
          ).catch(() => null);

          await gcpFetch(
            `https://serviceusage.googleapis.com/v1beta1/projects/${encodeURIComponent(
              projectId
            )}/services/iap.googleapis.com:generateServiceIdentity`,
            token,
            projectId,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: {},
              timeout: 8000,
            }
          ).catch(() => null);

          steps.push({
            step: 1,
            id: 'IAP_SERVICE_AGENT',
            title: 'Enable iap.googleapis.com & Provision IAP Service Agent',
            status: 'COMPLETED',
            detail: iapServiceAgent
              ? `Verified IAP Service Agent: ${iapServiceAgent}`
              : 'Enabled iap.googleapis.com control plane',
          });
        } catch (e) {
          steps.push({
            step: 1,
            id: 'IAP_SERVICE_AGENT',
            title: 'Enable iap.googleapis.com & Provision IAP Service Agent',
            status: 'WARNING',
            detail: e.message,
          });
        }
      } else {
        steps.push({
          step: 1,
          id: 'IAP_SERVICE_AGENT',
          title: 'Prepare Direct Cloud Run IAP Deactivation',
          status: 'COMPLETED',
          detail: `Target service: ${serviceName} (${region})`,
        });
      }

      // Step 2: Patch Cloud Run v2 Service (iapEnabled=true/false + invokerIamDisabled=false)
      let servicePatched = false;
      try {
        const patchPayload = {
          iapEnabled: targetEnabled,
          ...(targetEnabled ? { invokerIamDisabled: false } : {}),
        };
        const maskFields = targetEnabled
          ? 'iapEnabled,invokerIamDisabled'
          : 'iapEnabled';

        await gcpFetch(
          `${serviceUrl}?updateMask=${maskFields}`,
          token,
          projectId,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: patchPayload,
            timeout: 12000,
          }
        );
        servicePatched = true;
        steps.push({
          step: 2,
          id: 'CLOUD_RUN_IAP_ANNOTATION',
          title: targetEnabled
            ? 'Enable Native Cloud Run v2 IAP (iapEnabled=true & invokerIamDisabled=false)'
            : 'Disable Native Cloud Run v2 IAP (iapEnabled=false)',
          status: 'COMPLETED',
          detail: targetEnabled
            ? `Patched ${serviceName} via Cloud Run v2 REST API with iapEnabled=true, invokerIamDisabled=false`
            : `Patched ${serviceName} via Cloud Run v2 REST API with iapEnabled=false`,
        });
      } catch (patchErr) {
        steps.push({
          step: 2,
          id: 'CLOUD_RUN_IAP_ANNOTATION',
          title: 'Patch Cloud Run v2 iapEnabled Field',
          status: 'WARNING',
          detail:
            patchErr.response?.data?.error?.message || patchErr.message,
        });
      }

      // Step 3: Update Cloud Run Service IAM Policy (Grant/Revoke roles/run.invoker for IAP Service Agent & remove allUsers when enabling IAP)
      let updatedRunBindings = [];
      try {
        const currentPolicy = await gcpFetch(
          `${serviceUrl}:getIamPolicy`,
          token,
          projectId,
          { timeout: 6000 }
        ).catch(() => ({ bindings: [] }));
        const rawBindings = Array.isArray(currentPolicy?.bindings)
          ? currentPolicy.bindings
          : [];

        const saMember = iapServiceAgent
          ? `serviceAccount:${iapServiceAgent}`
          : '';

        let foundInvoker = false;
        const nextBindings = rawBindings
          .map((b) => {
            if (b.role !== 'roles/run.invoker') return b;
            foundInvoker = true;
            let members = Array.isArray(b.members) ? [...b.members] : [];
            if (targetEnabled) {
              // Remove allUsers so unauthenticated traffic cannot bypass IAP
              members = members.filter((m) => m !== 'allUsers');
              if (saMember && !members.includes(saMember)) {
                members.push(saMember);
              }
            } else if (saMember) {
              members = members.filter(
                (m) => m !== saMember && !String(m).includes('@gcp-sa-iap.')
              );
            }
            return { ...b, members };
          })
          .filter((b) => (b.members || []).length > 0);

        if (targetEnabled && !foundInvoker && saMember) {
          nextBindings.push({
            role: 'roles/run.invoker',
            members: [saMember],
          });
        }

        const setPolRes = await gcpFetch(
          `${serviceUrl}:setIamPolicy`,
          token,
          projectId,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: {
              policy: {
                bindings: nextBindings,
              },
            },
            timeout: 8000,
          }
        );
        updatedRunBindings = setPolRes?.bindings || nextBindings;
        steps.push({
          step: 3,
          id: 'CLOUD_RUN_INVOKER_BINDING',
          title: targetEnabled
            ? 'Lock Cloud Run Invoker IAM to IAP Service Agent (Remove allUsers)'
            : 'Remove IAP Service Agent from Cloud Run Invoker IAM',
          status: 'COMPLETED',
          detail: targetEnabled
            ? `Bound ${
                saMember || 'IAP Service Agent'
              } to roles/run.invoker & removed allUsers bypass`
            : `Removed ${saMember || 'IAP Service Agent'} from roles/run.invoker`,
        });
      } catch (iamErr) {
        steps.push({
          step: 3,
          id: 'CLOUD_RUN_INVOKER_BINDING',
          title: 'Update Cloud Run Invoker IAM Policy',
          status: 'WARNING',
          detail:
            iamErr.response?.data?.error?.message ||
            iamErr.message ||
            'IAP Service Agent still propagating',
        });
      }

      // Step 4: Bind roles/iap.httpsResourceAccessor on regional Cloud Run IAP Web resource
      const normalizedAccessors = (Array.isArray(accessors) ? accessors : [])
        .map((a) => String(a || '').trim())
        .filter(Boolean)
        .map((a) => {
          if (
            a.startsWith('user:') ||
            a.startsWith('group:') ||
            a.startsWith('domain:') ||
            a.startsWith('serviceAccount:')
          ) {
            return a;
          }
          if (a.includes('@')) return `user:${a}`;
          return `domain:${a}`;
        });

      if (
        targetEnabled &&
        normalizedAccessors.length === 0 &&
        account &&
        account.includes('@')
      ) {
        normalizedAccessors.push(`user:${account}`);
      }

      let boundAccessors = [...normalizedAccessors];
      if (targetEnabled && projectNumber && normalizedAccessors.length > 0) {
        const regionalIapUrl = `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
          projectNumber
        )}/iap_web/cloud_run-${encodeURIComponent(
          region
        )}/services/${encodeURIComponent(serviceName)}`;

        try {
          const curIapPol = await gcpFetch(
            `${regionalIapUrl}:getIamPolicy`,
            token,
            projectId,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: {},
              timeout: 6000,
            }
          ).catch(() => ({ bindings: [] }));

          const otherBindings = (curIapPol?.bindings || []).filter(
            (b) => b.role !== 'roles/iap.httpsResourceAccessor'
          );
          const nextIapBindings = [
            ...otherBindings,
            {
              role: 'roles/iap.httpsResourceAccessor',
              members: Array.from(new Set(normalizedAccessors)),
            },
          ];

          await gcpFetch(
            `${regionalIapUrl}:setIamPolicy`,
            token,
            projectId,
            {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: {
                policy: {
                  bindings: nextIapBindings,
                },
              },
              timeout: 8000,
            }
          );

          steps.push({
            step: 4,
            id: 'IAP_WEB_ACCESSORS',
            title:
              'Grant roles/iap.httpsResourceAccessor on Regional Cloud Run IAP Resource',
            status: 'COMPLETED',
            detail: `Granted Google Sign-In IAP access to: ${normalizedAccessors.join(
              ', '
            )}`,
          });
        } catch (iapWebErr) {
          // Fallback to project-level iap_web resource
          try {
            const projIapUrl = `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
              projectNumber
            )}/iap_web`;
            const curProjPol = await gcpFetch(
              `${projIapUrl}:getIamPolicy`,
              token,
              projectId,
              {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: {},
                timeout: 6000,
              }
            ).catch(() => ({ bindings: [] }));

            const existingAcc =
              (curProjPol?.bindings || []).find(
                (b) => b.role === 'roles/iap.httpsResourceAccessor'
              )?.members || [];
            const mergedMembers = Array.from(
              new Set([...existingAcc, ...normalizedAccessors])
            );
            const otherB = (curProjPol?.bindings || []).filter(
              (b) => b.role !== 'roles/iap.httpsResourceAccessor'
            );

            await gcpFetch(
              `${projIapUrl}:setIamPolicy`,
              token,
              projectId,
              {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: {
                  policy: {
                    bindings: [
                      ...otherB,
                      {
                        role: 'roles/iap.httpsResourceAccessor',
                        members: mergedMembers,
                      },
                    ],
                  },
                },
                timeout: 8000,
              }
            );
            boundAccessors = mergedMembers;
            steps.push({
              step: 4,
              id: 'IAP_WEB_ACCESSORS',
              title:
                'Grant roles/iap.httpsResourceAccessor on Project IAP Web Resource',
              status: 'COMPLETED',
              detail: `Granted project-level IAP Web access to: ${normalizedAccessors.join(
                ', '
              )}`,
            });
          } catch {
            steps.push({
              step: 4,
              id: 'IAP_WEB_ACCESSORS',
              title: 'Grant roles/iap.httpsResourceAccessor',
              status: 'WARNING',
              detail:
                iapWebErr.response?.data?.error?.message || iapWebErr.message,
            });
          }
        }
      } else {
        steps.push({
          step: 4,
          id: 'IAP_WEB_ACCESSORS',
          title: 'IAP Web Accessor Policy',
          status: 'COMPLETED',
          detail: targetEnabled
            ? 'Preserved existing roles/iap.httpsResourceAccessor bindings'
            : 'Direct Cloud Run IAP disabled; IAP Web bindings left untouched',
        });
      }

      // Optional Step 5: Configure Custom OAuth 2.0 Client ID & Secret for Org-less (@gmail.com) projects via iap_web:iapSettings
      if (
        targetEnabled &&
        projectNumber &&
        String(oauthClientId || '').trim() &&
        String(oauthClientSecret || '').trim()
      ) {
        try {
          await gcpFetch(
            `https://iap.googleapis.com/v1/projects/${encodeURIComponent(
              projectNumber
            )}/iap_web:iapSettings?updateMask=accessSettings.oauthSettings`,
            token,
            projectId,
            {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: {
                name: `projects/${projectNumber}/iap_web`,
                accessSettings: {
                  oauthSettings: {
                    clientId: String(oauthClientId).trim(),
                    clientSecret: String(oauthClientSecret).trim(),
                  },
                },
              },
              timeout: 8000,
            }
          );
          steps.push({
            step: 5,
            id: 'IAP_CUSTOM_OAUTH_CLIENT',
            title:
              'Bind Custom OAuth 2.0 Client ID & Secret (Org-Less Project iapSettings)',
            status: 'COMPLETED',
            detail: `Bound OAuth 2.0 Client ID ${String(oauthClientId).trim()} on projects/${projectNumber}/iap_web:iapSettings`,
          });
        } catch (oauthErr) {
          steps.push({
            step: 5,
            id: 'IAP_CUSTOM_OAUTH_CLIENT',
            title:
              'Bind Custom OAuth 2.0 Client ID & Secret (Org-Less Project iapSettings)',
            status: 'WARNING',
            detail:
              oauthErr.response?.data?.error?.message || oauthErr.message,
          });
        }
      }

      res.json({
        ok: true,
        projectId,
        projectNumber,
        isOrglessProject,
        oauthClientConfigured,
        oauthClientId,
        requiredRedirectUri: `https://iap.googleapis.com/v1/oauth/clientIds/${
          oauthClientId || '<YOUR_OAUTH_CLIENT_ID>'
        }:handleRedirect`,
        region,
        serviceName,
        iapEnabled: targetEnabled,
        servicePatched,
        iapServiceAgent,
        accessors: boundAccessors,
        updatedRunBindings,
        steps,
        cliCommands: {
          enableDirectIap: `gcloud beta run services update ${serviceName} --region=${region} --project=${projectId} --iap --no-allow-unauthenticated`,
          disableDirectIap: `gcloud beta run services update ${serviceName} --region=${region} --project=${projectId} --no-iap`,
          grantAccessor: `gcloud iap web add-iam-policy-binding --resource-type=cloud-run --service=${serviceName} --region=${region} --project=${projectId} --member="${
            boundAccessors[0] || `user:${account || 'you@example.com'}`
          }" --role="roles/iap.httpsResourceAccessor"`,
        },
        message: targetEnabled
          ? `Enabled App Engine-Style 1-Click Cloud IAP on "${serviceName}" (${region}) at $0.00/mo (Zero Load Balancer) & granted access to ${
              boundAccessors.join(', ') || 'authorized IAM principals'
            }!`
          : `Disabled Direct Cloud IAP on "${serviceName}" (${region}).`,
      });
    } catch (err) {
      res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to configure Cloud IAP on ${serviceName}`,
      });
    }
  }
);

// 10h. POST /api/project/:projectId/cloudrun/:region/:serviceName/traffic -> Live Traffic Splitting & 1-Tap Revision Rollback
app.post(
  '/api/project/:projectId/cloudrun/:region/:serviceName/traffic',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const { targetRevision = 'LATEST', canaryPercent = 0, canaryRevision = '' } =
      req.body || {};

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      const existing = await gcpFetch(serviceUrl, token, projectId, {
        timeout: 8000,
      });

      const traffic = [];
      const cleanCanaryPct = Math.min(99, Math.max(0, Number(canaryPercent || 0)));
      const primaryPct =
        cleanCanaryPct > 0 && canaryRevision ? 100 - cleanCanaryPct : 100;

      if (!targetRevision || targetRevision === 'LATEST') {
        traffic.push({
          type: 'TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST',
          percent: primaryPct,
        });
      } else {
        traffic.push({
          type: 'TRAFFIC_TARGET_ALLOCATION_TYPE_REVISION',
          revision: targetRevision,
          percent: primaryPct,
        });
      }

      if (cleanCanaryPct > 0 && canaryRevision) {
        traffic.push({
          type: 'TRAFFIC_TARGET_ALLOCATION_TYPE_REVISION',
          revision: canaryRevision,
          percent: cleanCanaryPct,
        });
      }

      const sanitizedForTraffic = sanitizeCloudRunV2ServiceForPatch(existing);
      const op = await gcpFetch(
        `${serviceUrl}?updateMask=traffic`,
        token,
        projectId,
        {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: {
            ...sanitizedForTraffic,
            traffic,
          },
          timeout: 10000,
        }
      );

      res.json({
        ok: true,
        operation: op,
        traffic,
        message:
          cleanCanaryPct > 0 && canaryRevision
            ? `Updated Cloud Run traffic split on "${serviceName}": ${primaryPct}% → ${targetRevision}, ${cleanCanaryPct}% → ${canaryRevision}.`
            : `Routed 100% of live HTTPS traffic on "${serviceName}" to ${targetRevision}!`,
      });
    } catch (err) {
      res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to update traffic routing on ${serviceName}`,
      });
    }
  }
);

// 10i. POST /api/project/:projectId/cloudrun/:region/:serviceName/seal-secrets -> Secret Manager & Env-Var Plaintext Leak Surgeon
// Automatically seals plaintext Cloud Run env vars into Google Cloud Secret Manager (`secretmanager.googleapis.com/v1`),
// binds `roles/secretmanager.secretAccessor` to the runtime Service Account, and patches the Cloud Run revision to mount `valueSource.secretKeyRef`.
app.post(
  '/api/project/:projectId/cloudrun/:region/:serviceName/seal-secrets',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const { envNames = [], inlineEnvVars } = req.body || {};

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      // 1. Ensure secretmanager.googleapis.com is enabled
      await gcpFetch(
        `https://serviceusage.googleapis.com/v1/projects/${encodeURIComponent(
          projectId
        )}/services/secretmanager.googleapis.com:enable`,
        token,
        projectId,
        { method: 'POST', timeout: 8000 }
      ).catch(() => null);

      // 2. Fetch existing Cloud Run v2 service
      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;
      const existing = await gcpFetch(serviceUrl, token, projectId, {
        timeout: 8000,
      });

      const container = existing.template?.containers?.[0] || {};
      const existingEnv = Array.isArray(container.env) ? container.env : [];
      const inlineParsed =
        inlineEnvVars !== undefined ? parseEnvVarsInput(inlineEnvVars) : [];
      const inlineMap = new Map(inlineParsed.map((e) => [e.name, e.value]));
      const mergedMap = new Map();
      for (const item of existingEnv) {
        if (item && item.name) mergedMap.set(item.name, item);
      }
      for (const [k, v] of inlineMap.entries()) {
        mergedMap.set(k, { name: k, value: v });
      }
      const currentEnv = Array.from(mergedMap.values());

      const sensitivePattern =
        /(?:SECRET|TOKEN|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY|AUTH_KEY|CLIENT_SECRET|DB_PASS|DATABASE_URL|REDIS_URL|STRIPE_KEY|OPENAI_API_KEY|GEMINI_API_KEY|JWT)/i;

      const targetNamesSet = new Set(
        Array.isArray(envNames) && envNames.length > 0
          ? envNames.map((n) => String(n).trim())
          : currentEnv
              .filter(
                (e) =>
                  e.name &&
                  e.value !== undefined &&
                  (sensitivePattern.test(e.name) ||
                    /^(?:AIzaSy|sk-[a-zA-Z0-9]{16,}|ghp_[a-zA-Z0-9]{16,}|postgres(?:ql)?:\/\/[^:]+:[^@]+@)/i.test(
                      String(e.value || '')
                    ))
              )
              .map((e) => e.name)
      );

      if (targetNamesSet.size === 0) {
        return res.status(400).json({
          error:
            'No plaintext secret environment variables were selected or detected on this Cloud Run service.',
        });
      }

      // 3. Resolve runtime service account email (prefers active custom SA if default compute SA was deleted)
      const runtimeSaEmail = await resolveRuntimeServiceAccount(
        projectId,
        token,
        existing.template?.serviceAccount
      );

      const sealedSecrets = [];
      const updatedEnv = [];

      for (const envItem of currentEnv) {
        if (
          !envItem.name ||
          envItem.value === undefined ||
          !targetNamesSet.has(envItem.name)
        ) {
          updatedEnv.push(envItem);
          continue;
        }

        const rawSecretId = `${serviceName}-${envItem.name}`
          .toLowerCase()
          .replace(/[^a-z0-9_-]/g, '-')
          .replace(/-+/g, '-')
          .replace(/^-|-$/g, '')
          .slice(0, 240);

        const secretBaseUrl = `https://secretmanager.googleapis.com/v1/projects/${encodeURIComponent(
          projectId
        )}/secrets`;

        // 3a. Create the Secret resource if it doesn't exist
        await gcpFetch(
          `${secretBaseUrl}?secretId=${encodeURIComponent(rawSecretId)}`,
          token,
          projectId,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: {
              replication: { automatic: {} },
              labels: {
                'managed-by': 'cloudpulse-2026',
                'cloudrun-service': String(serviceName)
                  .toLowerCase()
                  .replace(/[^a-z0-9_-]/g, '-'),
              },
            },
            timeout: 8000,
          }
        ).catch(() => null);

        // 3b. Add a new SecretVersion containing the base64-encoded plaintext value
        const base64Payload = Buffer.from(
          String(envItem.value),
          'utf8'
        ).toString('base64');
        await gcpFetch(
          `${secretBaseUrl}/${encodeURIComponent(rawSecretId)}:addVersion`,
          token,
          projectId,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: {
              payload: { data: base64Payload },
            },
            timeout: 8000,
          }
        );

        // 3c. Grant roles/secretmanager.secretAccessor to the Cloud Run runtime Service Account
        if (runtimeSaEmail) {
          try {
            const secretResourceUrl = `${secretBaseUrl}/${encodeURIComponent(
              rawSecretId
            )}`;
            const curPol = await gcpFetch(
              `${secretResourceUrl}:getIamPolicy`,
              token,
              projectId,
              { timeout: 5000 }
            ).catch(() => ({ bindings: [] }));
            const bindings = Array.isArray(curPol.bindings)
              ? [...curPol.bindings]
              : [];
            const memberStr = `serviceAccount:${runtimeSaEmail}`;
            const roleBinding = bindings.find(
              (b) => b.role === 'roles/secretmanager.secretAccessor'
            );
            if (roleBinding) {
              if (!roleBinding.members.includes(memberStr)) {
                roleBinding.members.push(memberStr);
              }
            } else {
              bindings.push({
                role: 'roles/secretmanager.secretAccessor',
                members: [memberStr],
              });
            }
            await gcpFetch(
              `${secretResourceUrl}:setIamPolicy`,
              token,
              projectId,
              {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: { policy: { ...curPol, bindings } },
                timeout: 6000,
              }
            );
          } catch {
            // ignore IAM binding non-fatal warning
          }
        }

        // 3d. Replace plaintext `value` with `valueSource.secretKeyRef`
        updatedEnv.push({
          name: envItem.name,
          valueSource: {
            secretKeyRef: {
              secret: rawSecretId,
              version: 'latest',
            },
          },
        });

        sealedSecrets.push({
          envName: envItem.name,
          secretId: rawSecretId,
          version: 'latest',
          runtimeServiceAccount: runtimeSaEmail || 'default',
        });
      }

      // 4. Patch the Cloud Run v2 Service template with the new `valueSource.secretKeyRef` mounts
      const sanitizedExisting = sanitizeCloudRunV2ServiceForPatch(existing);
      const updatedContainers = [...(sanitizedExisting.template?.containers || [])];
      updatedContainers[0] = {
        ...container,
        env: updatedEnv,
      };

      const patchBody = {
        ...sanitizedExisting,
        template: {
          ...sanitizedExisting.template,
          containers: updatedContainers,
        },
      };
      delete patchBody.template.revision;

      const op = await gcpFetch(
        `${serviceUrl}?updateMask=template.containers`,
        token,
        projectId,
        {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: patchBody,
          timeout: 12000,
        }
      );

      return res.json({
        ok: true,
        serviceName,
        region,
        sealedCount: sealedSecrets.length,
        sealedSecrets,
        operation: op,
        message: `Sealed ${sealedSecrets.length} plaintext env var(s) (${sealedSecrets
          .map((s) => `${s.envName} → secrets/${s.secretId}`)
          .join(', ')}) into Google Cloud Secret Manager and patched Cloud Run revision!`,
      });
    } catch (err) {
      return res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to seal plaintext secrets into Secret Manager for ${serviceName}`,
      });
    }
  }
);

// 10j. GET /api/project/:projectId/cloudrun/:region/:serviceName/revisions/:revisionName/autopsy
// Cloud Run Revision Time-Machine & Crash-Loop Autopsy:
// Compares the selected revision against the previous healthy revision (Image, CPU/Memory, Port, SA, Env & Secret Refs),
// fetches live container stderr/stdout & system audit logs from Cloud Logging (`logging.googleapis.com/v2`),
// and classifies the root cause with a 1-click remediation action.
app.get(
  '/api/project/:projectId/cloudrun/:region/:serviceName/revisions/:revisionName/autopsy',
  async (req, res) => {
    const { projectId, region, serviceName, revisionName } = req.params;
    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const baseUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;

      const [revsRes, logsRes] = await Promise.allSettled([
        gcpFetch(`${baseUrl}/revisions?pageSize=15`, token, projectId, {
          timeout: 7000,
        }),
        gcpFetch(
          `https://logging.googleapis.com/v2/entries:list`,
          token,
          projectId,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: {
              resourceNames: [`projects/${projectId}`],
              filter: `resource.type="cloud_run_revision" AND resource.labels.service_name="${serviceName}" AND resource.labels.revision_name="${revisionName}"`,
              orderBy: 'timestamp desc',
              pageSize: 35,
            },
            timeout: 7000,
          }
        ),
      ]);

      const rawRevisions =
        revsRes.status === 'fulfilled' ? revsRes.value?.revisions || [] : [];
      const targetRev =
        rawRevisions.find(
          (r) =>
            r.name?.split('/').pop() === revisionName || r.name === revisionName
        ) || rawRevisions[0];

      if (!targetRev) {
        return res.status(404).json({
          error: `Revision "${revisionName}" not found on Cloud Run service "${serviceName}".`,
        });
      }

      const targetShort = targetRev.name?.split('/').pop() || revisionName;
      const targetIdx = rawRevisions.findIndex(
        (r) => (r.name?.split('/').pop() || '') === targetShort
      );

      // Baseline revision for diff: either the next older revision in the list, or the newest healthy revision that isn't targetShort
      const baselineRev =
        rawRevisions.find((r, idx) => {
          const short = r.name?.split('/').pop() || '';
          if (short === targetShort) return false;
          const cond =
            r.terminalCondition ||
            (r.conditions || []).find((c) => c.type === 'Ready');
          return idx > targetIdx || cond?.state === 'CONDITION_SUCCEEDED';
        }) || null;

      const extractRevSpec = (r) => {
        if (!r) return null;
        const c = r.containers?.[0] || {};
        const lim = c.resources?.limits || {};
        const env = Array.isArray(c.env) ? c.env : [];
        const plainMap = {};
        const secretMap = {};
        for (const e of env) {
          if (!e?.name) continue;
          if (e.valueSource?.secretKeyRef) {
            const sec = String(e.valueSource.secretKeyRef.secret || '')
              .split('/')
              .pop();
            secretMap[e.name] = `${sec}@${
              e.valueSource.secretKeyRef.version || 'latest'
            }`;
          } else {
            plainMap[e.name] = String(e.value ?? '');
          }
        }
        const readyCond =
          r.terminalCondition ||
          (r.conditions || []).find((cd) => cd.type === 'Ready') ||
          {};
        return {
          shortName: r.name?.split('/').pop() || '',
          createTime: r.createTime || '',
          image: c.image || '',
          port: Number(c.ports?.[0]?.containerPort || 8080),
          cpu: String(lim.cpu || '1'),
          memory: String(lim.memory || '512Mi'),
          startupCpuBoost: Boolean(c.resources?.startupCpuBoost),
          cpuIdle: c.resources?.cpuIdle !== false,
          minInstances: Number(r.scaling?.minInstanceCount || 0),
          maxInstances: Number(r.scaling?.maxInstanceCount || 10),
          concurrency: Number(r.maxInstanceRequestConcurrency || 80),
          serviceAccount: r.serviceAccount || 'Default Compute SA',
          healthState: readyCond.state || 'CONDITION_SUCCEEDED',
          reason:
            readyCond.revisionReason ||
            readyCond.executionReason ||
            readyCond.reason ||
            '',
          message: readyCond.message || '',
          plainMap,
          secretMap,
        };
      };

      const targetSpec = extractRevSpec(targetRev);
      const baseSpec = extractRevSpec(baselineRev);

      // Compute Revision-to-Revision Configuration & Secret Diff
      let diffFromBaseline = null;
      if (baseSpec) {
        const targetEnvKeys = Object.keys(targetSpec.plainMap);
        const baseEnvKeys = Object.keys(baseSpec.plainMap);
        const addedEnvKeys = targetEnvKeys.filter(
          (k) => !baseEnvKeys.includes(k)
        );
        const removedEnvKeys = baseEnvKeys.filter(
          (k) => !targetEnvKeys.includes(k)
        );
        const modifiedEnvKeys = targetEnvKeys.filter(
          (k) =>
            baseEnvKeys.includes(k) &&
            targetSpec.plainMap[k] !== baseSpec.plainMap[k]
        );

        const allSecretKeys = Array.from(
          new Set([
            ...Object.keys(targetSpec.secretMap),
            ...Object.keys(baseSpec.secretMap),
          ])
        );
        const secretRefDiffs = allSecretKeys
          .filter((k) => targetSpec.secretMap[k] !== baseSpec.secretMap[k])
          .map((k) => ({
            envKey: k,
            from: baseSpec.secretMap[k] || 'Not Mounted',
            to: targetSpec.secretMap[k] || 'Unbound',
          }));

        diffFromBaseline = {
          baselineRevision: baseSpec.shortName,
          baselineCreateTime: baseSpec.createTime,
          imageChanged: {
            changed: targetSpec.image !== baseSpec.image,
            from: baseSpec.image,
            to: targetSpec.image,
          },
          resourcesChanged: {
            changed:
              targetSpec.cpu !== baseSpec.cpu ||
              targetSpec.memory !== baseSpec.memory,
            from: `${baseSpec.cpu} vCPU · ${baseSpec.memory}`,
            to: `${targetSpec.cpu} vCPU · ${targetSpec.memory}`,
          },
          portChanged: {
            changed: targetSpec.port !== baseSpec.port,
            from: baseSpec.port,
            to: targetSpec.port,
          },
          serviceAccountChanged: {
            changed: targetSpec.serviceAccount !== baseSpec.serviceAccount,
            from: baseSpec.serviceAccount,
            to: targetSpec.serviceAccount,
          },
          addedEnvKeys,
          removedEnvKeys,
          modifiedEnvKeys,
          secretRefDiffs,
          totalChangesCount:
            (targetSpec.image !== baseSpec.image ? 1 : 0) +
            (targetSpec.cpu !== baseSpec.cpu ||
            targetSpec.memory !== baseSpec.memory
              ? 1
              : 0) +
            (targetSpec.port !== baseSpec.port ? 1 : 0) +
            (targetSpec.serviceAccount !== baseSpec.serviceAccount ? 1 : 0) +
            addedEnvKeys.length +
            removedEnvKeys.length +
            modifiedEnvKeys.length +
            secretRefDiffs.length,
        };
      }

      // Format Cloud Logging entries for this revision
      const rawLogEntries =
        logsRes.status === 'fulfilled' ? logsRes.value?.entries || [] : [];
      const formattedLogs = rawLogEntries.map((entry, idx) => {
        const logNameShort = String(entry.logName || '').split('/').pop();
        const stream = logNameShort.includes('stderr')
          ? 'stderr'
          : logNameShort.includes('stdout')
          ? 'stdout'
          : logNameShort.includes('requests')
          ? 'http'
          : 'system';
        const text =
          entry.textPayload ||
          entry.jsonPayload?.message ||
          entry.jsonPayload?.error ||
          entry.protoPayload?.status?.message ||
          (entry.httpRequest
            ? `${entry.httpRequest.requestMethod || 'GET'} ${
                entry.httpRequest.status || 200
              } ${entry.httpRequest.requestUrl || '/'}`
            : JSON.stringify(entry.jsonPayload || {}));
        return {
          id: entry.insertId || `rev-log-${idx}`,
          timestamp: entry.timestamp || new Date().toISOString(),
          severity: entry.severity || 'INFO',
          stream,
          message: String(text || '').slice(0, 600),
        };
      });

      // Classify Root-Cause Diagnosis & 1-Click Fix
      const combinedEvidence = [
        targetSpec.reason,
        targetSpec.message,
        ...formattedLogs
          .filter(
            (l) =>
              l.severity === 'ERROR' ||
              l.severity === 'CRITICAL' ||
              l.severity === 'WARNING' ||
              l.stream === 'stderr'
          )
          .map((l) => l.message),
      ]
        .filter(Boolean)
        .join(' \n ');

      const isCrashed = targetSpec.healthState === 'CONDITION_FAILED';
      let diagnosis = {
        category: isCrashed ? 'APPLICATION_STARTUP_CRASH' : 'REVISION_HEALTHY',
        severity: isCrashed ? 'CRITICAL' : 'OK',
        headline: isCrashed
          ? `Revision ${targetShort} Failed Startup Readiness Check`
          : `Revision ${targetShort} Passed Readiness Probe & Is Healthy`,
        explanation:
          targetSpec.message ||
          (isCrashed
            ? 'The container exited or failed to bind to the configured port before the startup deadline.'
            : `Container is listening on TCP :${targetSpec.port} (${targetSpec.cpu} vCPU · ${targetSpec.memory}).`),
        recommendedActionType: isCrashed
          ? 'INSTANT_TRAFFIC_PIN'
          : 'NONE',
        recommendedActionLabel: isCrashed
          ? baseSpec
            ? ` 1-Click Instant Rollback to ${baseSpec.shortName}`
            : ' Enable Startup CPU Boost & Bump Memory'
          : '✓ Revision Ready',
        fixPayload: {},
      };

      if (/listen on the port|PORT=|HealthCheckContainerError/i.test(combinedEvidence)) {
        diagnosis = {
          category: 'PORT_LISTEN_TIMEOUT',
          severity: 'CRITICAL',
          headline: `Port Binding / Startup Timeout on TCP :${targetSpec.port} (${targetSpec.reason || 'HealthCheckContainerError'})`,
          explanation:
            targetSpec.message ||
            `Container did not listen on PORT=${targetSpec.port} within the startup timeout window.`,
          recommendedActionType: 'AUTO_FIX_CRASH',
          recommendedActionLabel: ` 1-Click Enable Startup CPU Boost & Verify Port :${targetSpec.port}`,
          fixPayload: {
            fixType: 'BUMP_MEMORY_AND_CPU_BOOST',
            port: targetSpec.port,
          },
        };
      } else if (
        /secretmanager|Secret .* not found|is in state DESTROYED|is in state DISABLED|Permission .*secretAccessor/i.test(
          combinedEvidence
        )
      ) {
        diagnosis = {
          category: 'SECRET_MANAGER_REF_ERROR',
          severity: 'CRITICAL',
          headline: `Broken or Unauthorized Secret Manager Reference (${targetSpec.reason || 'SecretError'})`,
          explanation:
            targetSpec.message ||
            'This revision references a Secret Manager version that is disabled, destroyed, deleted, or missing roles/secretmanager.secretAccessor.',
          recommendedActionType: 'OPEN_SECRET_STUDIO',
          recommendedActionLabel:
            ' Open Secret Dependency Healer (Re-Pin to Latest Enabled)',
          fixPayload: {},
        };
      } else if (
        /Memory limit|Out of memory|OOM|exit_code.*137|Killed/i.test(
          combinedEvidence
        )
      ) {
        diagnosis = {
          category: 'OUT_OF_MEMORY_OOM',
          severity: 'CRITICAL',
          headline: `Container Out-Of-Memory (OOMKilled at ${targetSpec.memory})`,
          explanation:
            targetSpec.message ||
            `The container exceeded its ${targetSpec.memory} memory limit during startup or request execution (Linux exit 137 / SIGKILL).`,
          recommendedActionType: 'AUTO_FIX_CRASH',
          recommendedActionLabel: ` 1-Click Double Memory Limit & Enable Startup CPU Boost`,
          fixPayload: {
            fixType: 'BUMP_MEMORY_AND_CPU_BOOST',
          },
        };
      }

      return res.json({
        ok: true,
        projectId,
        region,
        serviceName,
        revisionName: targetShort,
        targetRevision: targetSpec,
        baselineRevision: baseSpec,
        diffFromBaseline,
        diagnosis,
        logs: formattedLogs,
        scannedAt: new Date().toISOString(),
      });
    } catch (err) {
      return res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to run autopsy on revision ${revisionName}`,
      });
    }
  }
);

// 10k. POST /api/project/:projectId/cloudrun/:region/:serviceName/time-machine-restore
// Executes 1-Click Time-Machine Instant Traffic Rollback, Historical Revision Spec Clone, or Automated OOM/CPU-Boost Crash Remediation.
app.post(
  '/api/project/:projectId/cloudrun/:region/:serviceName/time-machine-restore',
  async (req, res) => {
    const { projectId, region, serviceName } = req.params;
    const {
      targetRevision,
      mode = 'INSTANT_TRAFFIC_PIN', // 'INSTANT_TRAFFIC_PIN' | 'CLONE_REVISION_SPEC' | 'AUTO_FIX_CRASH'
      fixPayload = {},
    } = req.body || {};

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) return res.status(401).json({ error: 'Not authenticated.' });

      const serviceUrl = `https://run.googleapis.com/v2/projects/${encodeURIComponent(
        projectId
      )}/locations/${encodeURIComponent(region)}/services/${encodeURIComponent(
        serviceName
      )}`;
      const existing = await gcpFetch(serviceUrl, token, projectId, {
        timeout: 8000,
      });
      const sanitized = sanitizeCloudRunV2ServiceForPatch(existing);

      if (mode === 'INSTANT_TRAFFIC_PIN') {
        if (!targetRevision) {
          return res.status(400).json({
            error: 'targetRevision is required for INSTANT_TRAFFIC_PIN.',
          });
        }
        const traffic = [
          {
            type: 'TRAFFIC_TARGET_ALLOCATION_TYPE_REVISION',
            revision: targetRevision,
            percent: 100,
          },
        ];
        const op = await gcpFetch(
          `${serviceUrl}?updateMask=traffic`,
          token,
          projectId,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: {
              ...sanitized,
              traffic,
            },
            timeout: 10000,
          }
        );
        recordFlightEvent(projectId, {
          action: 'CLOUDRUN_TIME_MACHINE_ROLLBACK',
          resourceType: 'CLOUD_RUN_SERVICE',
          resourceName: serviceName,
          region,
          summary: `Instant Time-Machine Rollback: Routed 100% of live traffic on "${serviceName}" to healthy revision "${targetRevision}"`,
        });
        return res.json({
          ok: true,
          mode,
          targetRevision,
          operation: op,
          message: ` Instant Rollback Complete: Routed 100% of live HTTPS traffic on "${serviceName}" back to revision "${targetRevision}"!`,
        });
      }

      if (mode === 'CLONE_REVISION_SPEC') {
        if (!targetRevision) {
          return res.status(400).json({
            error: 'targetRevision is required for CLONE_REVISION_SPEC.',
          });
        }
        const revObj = await gcpFetch(
          `${serviceUrl}/revisions/${encodeURIComponent(targetRevision)}`,
          token,
          projectId,
          { timeout: 8000 }
        );
        const revContainers = (revObj.containers || []).map((c) => {
          const cleanC = { ...c };
          delete cleanC.livenessProbe;
          delete cleanC.startupProbe;
          return cleanC;
        });

        const clonedTemplate = {
          ...sanitized.template,
          containers:
            revContainers.length > 0
              ? revContainers
              : sanitized.template?.containers,
          ...(revObj.scaling ? { scaling: revObj.scaling } : {}),
          ...(revObj.serviceAccount
            ? { serviceAccount: revObj.serviceAccount }
            : {}),
          ...(revObj.maxInstanceRequestConcurrency
            ? {
                maxInstanceRequestConcurrency:
                  revObj.maxInstanceRequestConcurrency,
              }
            : {}),
          ...(revObj.timeout ? { timeout: revObj.timeout } : {}),
          ...(revObj.executionEnvironment
            ? { executionEnvironment: revObj.executionEnvironment }
            : {}),
          ...(revObj.volumes ? { volumes: revObj.volumes } : {}),
          ...(revObj.vpcAccess ? { vpcAccess: revObj.vpcAccess } : {}),
          annotations: {
            ...(sanitized.template?.annotations || {}),
            'cloudpulse.google.com/cloned-from-revision': targetRevision,
            'cloudpulse.google.com/restored-at': new Date().toISOString(),
          },
        };
        delete clonedTemplate.revision;

        const traffic = [
          {
            type: 'TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST',
            percent: 100,
          },
        ];

        const op = await gcpFetch(
          `${serviceUrl}?updateMask=template,traffic`,
          token,
          projectId,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: {
              ...sanitized,
              template: clonedTemplate,
              traffic,
            },
            timeout: 12000,
          }
        );

        recordFlightEvent(projectId, {
          action: 'CLOUDRUN_TIME_MACHINE_CLONE',
          resourceType: 'CLOUD_RUN_SERVICE',
          resourceName: serviceName,
          region,
          summary: `Cloned historical revision "${targetRevision}" into a new LATEST revision on "${serviceName}"`,
        });

        return res.json({
          ok: true,
          mode,
          targetRevision,
          operation: op,
          message: ` Time-Machine Spec Restore Complete: Cloned "${targetRevision}" configuration into a brand-new LATEST revision on "${serviceName}"!`,
        });
      }

      if (mode === 'AUTO_FIX_CRASH') {
        const container = { ...(sanitized.template?.containers?.[0] || {}) };
        const curLimits = { ...(container.resources?.limits || {}) };
        const curMem = String(curLimits.memory || '512Mi');
        const memLadder = ['256Mi', '512Mi', '1Gi', '2Gi', '4Gi', '8Gi'];
        const curIdx = memLadder.indexOf(curMem);
        const nextMem =
          curIdx >= 0 && curIdx < memLadder.length - 1
            ? memLadder[curIdx + 1]
            : curMem === '128Mi'
            ? '512Mi'
            : '1Gi';

        curLimits.memory = nextMem;
        container.resources = {
          ...(container.resources || {}),
          limits: curLimits,
          startupCpuBoost: true,
        };
        if (fixPayload?.port) {
          container.ports = [
            { name: 'http1', containerPort: Number(fixPayload.port) || 8080 },
          ];
        }

        const nextTemplate = {
          ...sanitized.template,
          containers: [container],
          annotations: {
            ...(sanitized.template?.annotations || {}),
            'cloudpulse.google.com/crash-auto-fix-at': new Date().toISOString(),
          },
        };
        delete nextTemplate.revision;

        const op = await gcpFetch(
          `${serviceUrl}?updateMask=template`,
          token,
          projectId,
          {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: {
              ...sanitized,
              template: nextTemplate,
            },
            timeout: 12000,
          }
        );

        recordFlightEvent(projectId, {
          action: 'CLOUDRUN_CRASH_AUTO_FIX',
          resourceType: 'CLOUD_RUN_SERVICE',
          resourceName: serviceName,
          region,
          summary: `Applied 1-Click Crash Auto-Fix on "${serviceName}": Upgraded memory (${curMem} → ${nextMem}) & enabled Startup CPU Boost`,
        });

        return res.json({
          ok: true,
          mode,
          previousMemory: curMem,
          newMemory: nextMem,
          operation: op,
          message: ` Applied 1-Click Crash Auto-Fix on "${serviceName}": Upgraded memory (${curMem} → ${nextMem}) and enabled Startup CPU Boost!`,
        });
      }

      return res.status(400).json({ error: `Unsupported mode: ${mode}` });
    } catch (err) {
      return res.status(400).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to execute Time-Machine restore on ${serviceName}`,
      });
    }
  }
);

// ============================================================================
// INNOVATION #2: LOCAL DEVELOPER PORT-FORWARD & ZERO-PUBLIC-IP TUNNEL MANAGER
// (`127.0.0.1` Developer Bridge for Private Cloud Run Auth Proxy, Compute VM
//  IAP TCP Tunnel, and Private Cloud SQL / AlloyDB Auth Proxy)
// ============================================================================
const activeDeveloperTunnelsMap = new Map();

function findAvailableLocalPort(preferredPort = 8085) {
  return new Promise((resolve) => {
    const srv = net.createServer();
    srv.unref();
    srv.on('error', () => {
      // Fallback to OS-assigned random port or next port
      const fallbackSrv = net.createServer();
      fallbackSrv.unref();
      fallbackSrv.on('error', () => resolve(preferredPort));
      fallbackSrv.listen(0, '127.0.0.1', () => {
        const addr = fallbackSrv.address();
        const port = typeof addr === 'object' && addr ? addr.port : preferredPort;
        fallbackSrv.close(() => resolve(port));
      });
    });
    srv.listen(preferredPort, '127.0.0.1', () => {
      srv.close(() => resolve(preferredPort));
    });
  });
}

function serializeTunnelEntry(t) {
  return {
    tunnelId: t.tunnelId,
    projectId: t.projectId,
    targetType: t.targetType, // 'CLOUD_RUN_PROXY' | 'COMPUTE_IAP_TCP' | 'CLOUD_SQL_IAP'
    resourceName: t.resourceName,
    region: t.region || '',
    zone: t.zone || '',
    localHost: '127.0.0.1',
    localPort: t.localPort,
    remotePort: t.remotePort,
    localEndpoint: `127.0.0.1:${t.localPort}`,
    localUrl:
      t.targetType === 'CLOUD_RUN_PROXY' || [80, 443, 3000, 5173, 8000, 8080, 8888].includes(Number(t.remotePort))
        ? `http://127.0.0.1:${t.localPort}`
        : `tcp://127.0.0.1:${t.localPort}`,
    status: t.status, // 'STARTING' | 'ACTIVE_LISTENING' | 'CLI_READY' | 'STOPPED' | 'ERROR'
    pid: t.pid || null,
    engine: t.engine,
    cliCommand: t.cliCommand,
    clientSnippets: t.clientSnippets || {},
    logs: (t.logs || []).slice(-18),
    startedAt: t.startedAt,
    zeroPublicIpSavingsMonthlyUsd: 7.3,
  };
}

// 10c. GET /api/project/:projectId/tunnels -> List active 127.0.0.1 developer tunnels
app.get('/api/project/:projectId/tunnels', async (req, res) => {
  const { projectId } = req.params;
  const projectTunnels = [];
  for (const [, entry] of activeDeveloperTunnelsMap.entries()) {
    if (entry.projectId === projectId) {
      projectTunnels.push(serializeTunnelEntry(entry));
    }
  }
  return res.json({
    projectId,
    activeCount: projectTunnels.filter(
      (t) => t.status === 'ACTIVE_LISTENING' || t.status === 'STARTING' || t.status === 'CLI_READY'
    ).length,
    tunnels: projectTunnels.sort(
      (a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime()
    ),
    iapCidrRange: '35.235.240.0/20',
    staticIpSavingsPerResourceMonthly: 7.3,
  });
});

// 10d. POST /api/project/:projectId/tunnels/start -> Spawn or register a 127.0.0.1 Developer Tunnel
app.post('/api/project/:projectId/tunnels/start', async (req, res) => {
  const { projectId } = req.params;
  const {
    targetType = 'CLOUD_RUN_PROXY', // 'CLOUD_RUN_PROXY' | 'COMPUTE_IAP_TCP' | 'CLOUD_SQL_IAP'
    resourceName = '',
    region = 'us-central1',
    zone = 'us-central1-a',
    remotePort = 8080,
    preferredLocalPort = 8085,
    dbEngine = 'POSTGRES', // 'POSTGRES' | 'MYSQL' | 'ALLOYDB'
  } = req.body || {};

  if (!resourceName) {
    return res.status(400).json({ error: 'resourceName is required to start a local tunnel.' });
  }

  // Check if an existing tunnel for this exact resource + remotePort is already running
  const existingKey = `${projectId}:${targetType}:${resourceName}:${remotePort}`;
  if (activeDeveloperTunnelsMap.has(existingKey)) {
    const existing = activeDeveloperTunnelsMap.get(existingKey);
    if (existing.status === 'ACTIVE_LISTENING' || existing.status === 'STARTING' || existing.status === 'CLI_READY') {
      return res.json({
        ok: true,
        reused: true,
        tunnel: serializeTunnelEntry(existing),
        message: ` Local tunnel to "${resourceName}" is already active on 127.0.0.1:${existing.localPort}!`,
      });
    }
  }

  const reqPort = Math.max(1024, Math.min(65530, Number(preferredLocalPort) || 8085));
  const localPort = await findAvailableLocalPort(reqPort);
  const cleanRemotePort = Number(remotePort) || 8080;

  let cliCommand = '';
  let spawnArgs = [];
  let clientSnippets = {};

  if (targetType === 'CLOUD_RUN_PROXY') {
    cliCommand = `gcloud run services proxy ${resourceName} --region=${region} --project=${projectId} --port=${localPort}`;
    spawnArgs = [
      'run',
      'services',
      'proxy',
      resourceName,
      `--region=${region}`,
      `--project=${projectId}`,
      `--port=${localPort}`,
      '--quiet',
    ];
    clientSnippets = {
      curl: `curl -i http://127.0.0.1:${localPort}/`,
      fetchJs: `const res = await fetch("http://127.0.0.1:${localPort}/api/health");`,
      browserUrl: `http://127.0.0.1:${localPort}`,
      directTokenCurl: `curl -H "Authorization: Bearer $(gcloud auth print-identity-token)" https://${resourceName}-${region}.a.run.app`,
    };
  } else if (targetType === 'COMPUTE_IAP_TCP') {
    cliCommand = `gcloud compute start-iap-tunnel ${resourceName} ${cleanRemotePort} --local-host-port=127.0.0.1:${localPort} --zone=${zone} --project=${projectId}`;
    spawnArgs = [
      'compute',
      'start-iap-tunnel',
      resourceName,
      String(cleanRemotePort),
      `--local-host-port=127.0.0.1:${localPort}`,
      `--zone=${zone}`,
      `--project=${projectId}`,
      '--quiet',
    ];
    clientSnippets =
      cleanRemotePort === 22
        ? {
            ssh: `ssh -p ${localPort} -o StrictHostKeyChecking=no 127.0.0.1`,
            vscodeRemote: `code --remote ssh-remote+127.0.0.1:${localPort} /home`,
            scp: `scp -P ${localPort} ./local-file.txt 127.0.0.1:~/`,
          }
        : cleanRemotePort === 5432
        ? {
            psql: `psql "host=127.0.0.1 port=${localPort} user=postgres dbname=postgres sslmode=prefer"`,
            dsn: `postgresql://postgres@127.0.0.1:${localPort}/postgres`,
          }
        : cleanRemotePort === 3306
        ? {
            mysql: `mysql -h 127.0.0.1 -P ${localPort} -u root -p`,
            dsn: `mysql://root@127.0.0.1:${localPort}/app`,
          }
        : cleanRemotePort === 6379
        ? {
            redisCli: `redis-cli -h 127.0.0.1 -p ${localPort}`,
            dsn: `redis://127.0.0.1:${localPort}`,
          }
        : {
            curl: `curl -i http://127.0.0.1:${localPort}/`,
            browserUrl: `http://127.0.0.1:${localPort}`,
          };
  } else {
    // CLOUD_SQL_IAP / ALLOYDB Auth Proxy
    const isMysql = String(dbEngine).toUpperCase().includes('MYSQL') || cleanRemotePort === 3306;
    const isAlloy = String(dbEngine).toUpperCase().includes('ALLOY');
    cliCommand = isAlloy
      ? `alloydb-auth-proxy "projects/${projectId}/locations/${region}/clusters/${resourceName}/instances/${resourceName}-primary" --auto-iam-authn --private-ip --address=127.0.0.1 --port=${localPort}`
      : `cloud-sql-proxy "${projectId}:${region}:${resourceName}" --auto-iam-authn --private-ip --address=127.0.0.1 --port=${localPort}`;
    spawnArgs = [
      'beta',
      'sql',
      'connect',
      resourceName,
      `--project=${projectId}`,
      '--quiet',
    ];
    clientSnippets = isMysql
      ? {
          mysqlCli: `mysql -h 127.0.0.1 -P ${localPort} -u iam_user --enable-cleartext-plugin`,
          prismaDsn: `DATABASE_URL="mysql://iam_user@127.0.0.1:${localPort}/production_db"`,
          jdbc: `jdbc:mysql://127.0.0.1:${localPort}/production_db`,
        }
      : {
          psqlCli: `psql "host=127.0.0.1 port=${localPort} user=iam_service_account dbname=postgres sslmode=disable"`,
          prismaDsn: `DATABASE_URL="postgresql://iam_service_account@127.0.0.1:${localPort}/production_db?sslmode=disable"`,
          sqlalchemyDsn: `postgresql+psycopg2://iam_service_account@127.0.0.1:${localPort}/production_db`,
        };
  }

  const tunnelEntry = {
    tunnelId: existingKey,
    projectId,
    targetType,
    resourceName,
    region,
    zone,
    localPort,
    remotePort: cleanRemotePort,
    status: 'STARTING',
    pid: null,
    proc: null,
    engine:
      targetType === 'CLOUD_RUN_PROXY'
        ? 'gcloud run services proxy (Automatic OIDC Bearer Injection)'
        : targetType === 'COMPUTE_IAP_TCP'
        ? 'gcloud compute start-iap-tunnel (Zero-Public-IP IAP TCP 35.235.240.0/20)'
        : 'Cloud SQL / AlloyDB IAM Auth Proxy v2 (mTLS + Short-Lived OAuth2)',
    cliCommand,
    clientSnippets,
    logs: [
      `[${new Date().toISOString().slice(11, 19)}] Initializing ${targetType} bridge on 127.0.0.1:${localPort} → ${resourceName}:${cleanRemotePort}...`,
      `[${new Date().toISOString().slice(11, 19)}] Command: ${cliCommand}`,
    ],
    startedAt: new Date().toISOString(),
  };

  activeDeveloperTunnelsMap.set(existingKey, tunnelEntry);

  // Spawn real background gcloud tunnel for CLOUD_RUN_PROXY and COMPUTE_IAP_TCP when gcloud is available
  if (targetType === 'CLOUD_RUN_PROXY' || targetType === 'COMPUTE_IAP_TCP') {
    try {
      const child = spawn('gcloud', spawnArgs, {
        env: ATTRIBUTION_ENV,
        stdio: ['ignore', 'pipe', 'pipe'],
      });
      tunnelEntry.pid = child.pid || null;
      tunnelEntry.proc = child;
      tunnelEntry.status = 'ACTIVE_LISTENING';
      tunnelEntry.logs.push(
        `[${new Date().toISOString().slice(11, 19)}] Spawned background tunnel daemon (PID ${child.pid || 'local'}) listening on 127.0.0.1:${localPort}`
      );

      const appendLog = (chunk) => {
        const lines = String(chunk || '')
          .split('\n')
          .map((l) => l.trim())
          .filter(Boolean);
        for (const line of lines) {
          tunnelEntry.logs.push(`[${new Date().toISOString().slice(11, 19)}] ${line.slice(0, 220)}`);
          if (/listening on|Testing if tunnel connection works/i.test(line)) {
            tunnelEntry.status = 'ACTIVE_LISTENING';
          }
        }
        if (tunnelEntry.logs.length > 30) {
          tunnelEntry.logs = tunnelEntry.logs.slice(-30);
        }
      };

      child.stdout?.on('data', appendLog);
      child.stderr?.on('data', appendLog);
      child.on('error', (err) => {
        tunnelEntry.status = 'CLI_READY';
        tunnelEntry.logs.push(
          `[${new Date().toISOString().slice(11, 19)}] Local CLI ready mode (${err.message}). Run the command below in your terminal.`
        );
      });
      child.on('exit', (code) => {
        if (tunnelEntry.status !== 'STOPPED') {
          tunnelEntry.status = code === 0 ? 'STOPPED' : 'CLI_READY';
          tunnelEntry.logs.push(
            `[${new Date().toISOString().slice(11, 19)}] Process exited (code ${code ?? 0}). Copy-ready CLI tunnel config remains active.`
          );
        }
      });
    } catch (spawnErr) {
      tunnelEntry.status = 'CLI_READY';
      tunnelEntry.logs.push(
        `[${new Date().toISOString().slice(11, 19)}] Ready in Copy-CLI mode: ${spawnErr.message}`
      );
    }
  } else {
    tunnelEntry.status = 'CLI_READY';
    tunnelEntry.logs.push(
      `[${new Date().toISOString().slice(11, 19)}] Generated Zero-Password IAM Auth Proxy v2 bridge & ORM connection strings on 127.0.0.1:${localPort}.`
    );
  }

  // Wait up to 900ms to capture initial startup logs from gcloud
  await new Promise((r) => setTimeout(r, 850));

  recordFlightEvent(projectId, {
    action: 'START_LOCAL_DEV_TUNNEL',
    resourceType: targetType,
    resourceName,
    region: region || zone,
    summary: `Started 127.0.0.1:${localPort} Zero-Public-IP Developer Tunnel → ${resourceName}:${cleanRemotePort}`,
  });

  return res.json({
    ok: true,
    tunnel: serializeTunnelEntry(tunnelEntry),
    message: ` Local Zero-Public-IP Tunnel active on 127.0.0.1:${localPort} → ${resourceName}:${cleanRemotePort} (Saves $7.30/mo vs Public IPv4)!`,
  });
});

// 10e. POST /api/project/:projectId/tunnels/stop -> Terminate an active 127.0.0.1 tunnel
app.post('/api/project/:projectId/tunnels/stop', async (req, res) => {
  const { projectId } = req.params;
  const { tunnelId } = req.body || {};

  if (!tunnelId || !activeDeveloperTunnelsMap.has(tunnelId)) {
    return res.json({
      ok: true,
      message: 'Tunnel already stopped.',
    });
  }

  const entry = activeDeveloperTunnelsMap.get(tunnelId);
  entry.status = 'STOPPED';
  if (entry.proc) {
    try {
      entry.proc.kill('SIGTERM');
    } catch {
      // ignore
    }
  }
  activeDeveloperTunnelsMap.delete(tunnelId);

  return res.json({
    ok: true,
    tunnelId,
    projectId,
    message: ` Closed local tunnel 127.0.0.1:${entry.localPort} (${entry.resourceName}).`,
  });
});

// 10f. POST /api/project/:projectId/tunnels/probe -> Probe a live 127.0.0.1 TCP/HTTP tunnel port
app.post('/api/project/:projectId/tunnels/probe', async (req, res) => {
  const { tunnelId, pathSuffix = '/' } = req.body || {};
  const entry = tunnelId ? activeDeveloperTunnelsMap.get(tunnelId) : null;
  if (!entry) {
    return res.status(404).json({ error: 'Tunnel not found or already closed.' });
  }

  const t0 = Date.now();
  // TCP socket reachability test on 127.0.0.1:localPort
  const tcpResult = await new Promise((resolve) => {
    const sock = new net.Socket();
    let settled = false;
    const finish = (ok, detail) => {
      if (settled) return;
      settled = true;
      try {
        sock.destroy();
      } catch {
        // ignore
      }
      resolve({ ok, detail, rttMs: Date.now() - t0 });
    };
    sock.setTimeout(2500);
    sock.once('connect', () => finish(true, `TCP handshake succeeded on 127.0.0.1:${entry.localPort}`));
    sock.once('timeout', () => finish(false, `TCP connection timed out after 2500ms on 127.0.0.1:${entry.localPort}`));
    sock.once('error', (err) => finish(false, err.message));
    sock.connect(entry.localPort, '127.0.0.1');
  });

  let httpProbe = null;
  if (tcpResult.ok && entry.targetType === 'CLOUD_RUN_PROXY') {
    try {
      const cleanPath = String(pathSuffix || '/').startsWith('/') ? pathSuffix : `/${pathSuffix}`;
      const resp = await gcpHttp.get(`http://127.0.0.1:${entry.localPort}${cleanPath}`, {
        timeout: 4500,
        validateStatus: () => true,
      });
      httpProbe = {
        statusCode: resp.status,
        contentType: resp.headers?.['content-type'] || 'text/plain',
        bodyPreview:
          typeof resp.data === 'string'
            ? resp.data.slice(0, 260)
            : JSON.stringify(resp.data).slice(0, 260),
      };
    } catch (e) {
      httpProbe = { error: e.message };
    }
  }

  return res.json({
    ok: true,
    tunnel: serializeTunnelEntry(entry),
    tcpReachable: tcpResult.ok,
    rttMs: tcpResult.rttMs,
    detail: tcpResult.detail,
    httpProbe,
  });
});

// ============================================================================
// INNOVATION #3: LIVE CLOUD AUDIT "WHO-CHANGED-WHAT" ACTIVITY TIMELINE &
// 1-CLICK CHANGE INSPECTOR (`logging.googleapis.com/v2` `cloudaudit.googleapis.com/activity`)
// ============================================================================
function classifyAuditActivityMethod(serviceName = '', methodName = '', resourceName = '') {
  const m = String(methodName || '');
  const s = String(serviceName || '');
  const lowerM = m.toLowerCase();
  const shortResource = String(resourceName || '').split('/').pop() || resourceName || 'resource';

  let actionCategory = 'UPDATE';
  if (/delete|destroy|remove|purge|drop|unlink/i.test(lowerM)) {
    actionCategory = 'DELETE';
  } else if (/SetIamPolicy|Grant|Revoke|CreateServiceAccountKey|DisableServiceAccountKey/i.test(m)) {
    actionCategory = 'IAM_SECURITY';
  } else if (/create|insert|deploy|addversion|enable/i.test(lowerM)) {
    actionCategory = 'CREATE';
  } else if (/stop|start|reset|suspend|resume/i.test(lowerM)) {
    actionCategory = 'POWER';
  }

  let humanSummary = `${m.split('.').slice(-2).join('.')} on ${shortResource}`;
  let reverseCli = `gcloud logging read 'protoPayload.methodName="${m}"' --project=${
    String(resourceName).match(/projects\/([^/]+)/)?.[1] || 'PROJECT_ID'
  } --limit=5`;

  if (s.includes('run.googleapis.com')) {
    if (lowerM.includes('createservice')) {
      humanSummary = `Deployed new Cloud Run service "${shortResource}"`;
      reverseCli = `gcloud run services delete ${shortResource} --quiet`;
    } else if (lowerM.includes('updateservice') || lowerM.includes('replaceservice')) {
      humanSummary = `Updated Cloud Run service "${shortResource}" revision / traffic spec`;
      reverseCli = `gcloud run services describe ${shortResource} --format=yaml`;
    } else if (lowerM.includes('deleteservice')) {
      humanSummary = `Deleted Cloud Run service "${shortResource}"`;
    } else if (lowerM.includes('setiampolicy')) {
      humanSummary = `Modified Cloud Run Invoker IAM policy on "${shortResource}"`;
    }
  } else if (s.includes('compute.googleapis.com')) {
    if (lowerM.includes('instances.insert')) {
      humanSummary = `Provisioned Compute Engine VM "${shortResource}"`;
      reverseCli = `gcloud compute instances delete ${shortResource} --quiet`;
    } else if (lowerM.includes('instances.delete')) {
      humanSummary = `Deleted Compute Engine VM "${shortResource}"`;
    } else if (lowerM.includes('instances.stop')) {
      humanSummary = `Stopped Compute Engine VM "${shortResource}" ($0/hr vCPU)`;
      reverseCli = `gcloud compute instances start ${shortResource}`;
    } else if (lowerM.includes('instances.start')) {
      humanSummary = `Started Compute Engine VM "${shortResource}"`;
      reverseCli = `gcloud compute instances stop ${shortResource}`;
    } else if (lowerM.includes('firewalls.')) {
      humanSummary = `${actionCategory === 'DELETE' ? 'Deleted' : 'Updated'} VPC Firewall Rule "${shortResource}"`;
      reverseCli = `gcloud compute firewall-rules describe ${shortResource}`;
    }
  } else if (s.includes('secretmanager.googleapis.com')) {
    if (lowerM.includes('addsecretversion')) {
      humanSummary = `Rotated / added encrypted Secret Manager version on "${shortResource}"`;
    } else if (lowerM.includes('destroysecretversion')) {
      humanSummary = `Permanently destroyed Secret Manager version on "${shortResource}"`;
    } else if (lowerM.includes('disablesecretversion')) {
      humanSummary = `Disabled Secret Manager version on "${shortResource}" ($0.00/mo)`;
    } else if (lowerM.includes('deletesecret')) {
      humanSummary = `Deleted Secret Manager secret "${shortResource}"`;
    }
  } else if (s.includes('storage.googleapis.com')) {
    humanSummary = `${actionCategory === 'CREATE' ? 'Created' : actionCategory === 'DELETE' ? 'Deleted' : 'Modified'} Cloud Storage bucket "${shortResource}"`;
  } else if (s.includes('bigquery.googleapis.com')) {
    humanSummary = `Executed BigQuery ${m.split('.').pop()} on "${shortResource}"`;
  } else if (s.includes('iam.googleapis.com') || lowerM.includes('setiampolicy')) {
    humanSummary = `Modified IAM Policy / Service Account on "${shortResource}"`;
  }

  return {
    actionCategory,
    humanSummary,
    reverseCli,
    shortResource,
  };
}

app.get('/api/project/:projectId/audit-timeline', async (req, res) => {
  const { projectId } = req.params;
  const { token, account } = await resolveRequestAuth(req);
  if (!token) {
    return res.status(401).json({ error: 'Not authenticated.' });
  }

  const serviceFilter = String(req.query.service || 'ALL').trim();
  const limit = Math.min(100, Math.max(10, Number(req.query.limit) || 45));

  try {
    let filterStr = `logName:"cloudaudit.googleapis.com%2Factivity" OR logName:"cloudaudit.googleapis.com%2Fsystem_event"`;
    if (serviceFilter !== 'ALL') {
      filterStr = `(${filterStr}) AND protoPayload.serviceName="${serviceFilter}"`;
    }

    const logResp = await gcpFetch(
      `https://logging.googleapis.com/v2/entries:list`,
      token,
      projectId,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: {
          resourceNames: [`projects/${projectId}`],
          filter: filterStr,
          orderBy: 'timestamp desc',
          pageSize: limit,
        },
        timeout: 9000,
      }
    );

    const rawEntries = Array.isArray(logResp?.entries) ? logResp.entries : [];
    const auditEvents = rawEntries.map((entry, idx) => {
      const proto = entry.protoPayload || {};
      const serviceName = proto.serviceName || entry.resource?.type || 'gcp.service';
      const methodName = proto.methodName || 'AdminActivity';
      const resourceName =
        proto.resourceName ||
        entry.resource?.labels?.service_name ||
        entry.resource?.labels?.instance_id ||
        entry.resource?.labels?.bucket_name ||
        projectId;
      const principalEmail =
        proto.authenticationInfo?.principalEmail ||
        proto.authenticationInfo?.principalSubject ||
        account ||
        'system@google.com';
      const callerIp = proto.requestMetadata?.callerIp || 'internal';
      const userAgent = proto.requestMetadata?.callerSuppliedUserAgent || 'gcloud / REST';
      const statusObj = proto.status || {};
      const isError =
        entry.severity === 'ERROR' ||
        (typeof statusObj.code === 'number' && statusObj.code !== 0);

      // Extract IAM policy bindings delta if present
      const policyDelta =
        proto.serviceData?.policyDelta?.bindingDeltas ||
        proto.metadata?.datasetChange?.bindingDeltas ||
        [];

      const classified = classifyAuditActivityMethod(
        serviceName,
        methodName,
        resourceName
      );

      return {
        id: entry.insertId || `audit-${idx}-${entry.timestamp}`,
        timestamp: entry.timestamp || new Date().toISOString(),
        severity: isError ? 'ERROR' : entry.severity || 'NOTICE',
        serviceName,
        methodName,
        resourceType: entry.resource?.type || 'project',
        resourceName,
        shortResource: classified.shortResource,
        region:
          entry.resource?.labels?.location ||
          entry.resource?.labels?.zone ||
          entry.resource?.labels?.region ||
          'global',
        principalEmail,
        isServiceAccount: principalEmail.endsWith('.gserviceaccount.com'),
        callerIp,
        userAgent: String(userAgent).slice(0, 90),
        actionCategory: classified.actionCategory,
        humanSummary: classified.humanSummary,
        reverseCli: classified.reverseCli,
        statusMessage: statusObj.message || (isError ? 'Operation failed' : 'OK (0)'),
        policyDelta,
        requestPayload: proto.request || null,
        responsePayload: proto.response || null,
        source: 'CLOUD_AUDIT_LOGS',
      };
    });

    // Also merge any recent in-session Flight Recorder mutations so immediate actions appear even before Cloud Logging indexes them
    const sessionLedger = flightRecorderByProject.get(projectId) || [];
    const sessionEvents = sessionLedger.slice(0, 15).map((fl, i) => ({
      id: `flight-${fl.id || i}`,
      timestamp: fl.timestamp || new Date().toISOString(),
      severity: 'NOTICE',
      serviceName: `${String(fl.resourceType || 'cloudpulse').toLowerCase()}.googleapis.com`,
      methodName: fl.action || 'CloudPulseMutation',
      resourceType: fl.resourceType || 'CLOUD_RESOURCE',
      resourceName: fl.resourceName || projectId,
      shortResource: fl.resourceName || projectId,
      region: fl.region || 'global',
      principalEmail: account || 'active-session-owner',
      isServiceAccount: false,
      callerIp: '127.0.0.1 (CloudPulse Studio)',
      userAgent: 'CloudPulse 2026 Control Plane',
      actionCategory: /DELETE|DESTROY|EXTERMINATE/i.test(fl.action)
        ? 'DELETE'
        : /IAM|SECRET|GRANT/i.test(fl.action)
        ? 'IAM_SECURITY'
        : 'UPDATE',
      humanSummary: fl.summary || `${fl.action} on ${fl.resourceName}`,
      reverseCli: fl.undoHint || `gcloud projects describe ${projectId}`,
      statusMessage: 'OK (Verified Session Action)',
      policyDelta: [],
      requestPayload: fl.details || null,
      responsePayload: null,
      source: 'SESSION_FLIGHT_RECORDER',
    }));

    const combined = [...auditEvents, ...sessionEvents].sort(
      (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    );

    // Compute summary breakdown
    const actorCounts = {};
    const categoryCounts = { CREATE: 0, UPDATE: 0, DELETE: 0, IAM_SECURITY: 0, POWER: 0 };
    for (const ev of combined) {
      actorCounts[ev.principalEmail] = (actorCounts[ev.principalEmail] || 0) + 1;
      categoryCounts[ev.actionCategory] = (categoryCounts[ev.actionCategory] || 0) + 1;
    }

    return res.json({
      projectId,
      totalEvents: combined.length,
      cloudAuditCount: auditEvents.length,
      sessionLedgerCount: sessionEvents.length,
      categoryCounts,
      topActors: Object.entries(actorCounts)
        .map(([email, count]) => ({ email, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 6),
      events: combined,
      alwaysFreeTierInfo:
        'Cloud Audit Admin Activity logs (cloudaudit.googleapis.com/activity) are 100% Always Free and retained for 400 days at $0.00/mo.',
    });
  } catch (err) {
    return res.status(400).json({
      error:
        err.response?.data?.error?.message ||
        err.message ||
        'Failed to query Cloud Audit Activity logs',
    });
  }
});

// ============================================================================
// MOONSHOT 2026: NEURAL CHRONO-LOG & TRACE STUDIO ENGINE
//  1. Semantic Drain3 Log Pattern Clustering (tokenizes UUIDs, IPs, ms, numbers)
//  2. Cross-Service Distributed Trace Waterfall (`traceId` span stitching)
//  3. Natural Language <-> LQL + BigQuery Log Analytics SQL (`_Default._AllLogs`)
//  4. Zero-JSON-Digging Smart Flattener & `±30s` Time-Travel Causal Context
//  5. Log FinOps Byte-Burn Meter & 1-Click `_Default` Sink Exclusion Builder
//  6. Live DLP Secret & PII Leak Redaction Radar
// ============================================================================
const customSinkExclusionsByProject = new Map();

const NLP_STOP_WORDS = new Set([
  'a', 'an', 'the', 'show', 'me', 'find', 'search', 'list', 'get', 'all',
  'logs', 'log', 'entries', 'entry', 'events', 'event', 'where', 'when',
  'that', 'which', 'have', 'has', 'had', 'in', 'on', 'at', 'from', 'for',
  'with', 'by', 'to', 'of', 'is', 'are', 'was', 'were', 'be', 'been',
  'please', 'can', 'you', 'why', 'what', 'how', 'any', 'only', 'just',
]);

function porterStemWord(word = '') {
  let w = String(word || '').toLowerCase().replace(/[^a-z0-9_.-]/g, '');
  if (w.length <= 3) return w;
  if (w.endsWith('ies') && w.length > 4) w = w.slice(0, -3) + 'y';
  else if (w.endsWith('es') && w.length > 4) w = w.slice(0, -2);
  else if (w.endsWith('s') && !w.endsWith('ss') && w.length > 3) w = w.slice(0, -1);
  if (w.endsWith('ing') && w.length > 5) w = w.slice(0, -3);
  else if (w.endsWith('ed') && w.length > 4) w = w.slice(0, -2);
  if (w.endsWith('ation') && w.length > 7) w = w.slice(0, -5) + 'e';
  if (w.endsWith('ion') && w.length > 5) w = w.slice(0, -3);
  return w;
}

function nlpTokenizeAndStem(rawText = '') {
  const rawTokens = String(rawText || '')
    .toLowerCase()
    .split(/[^a-z0-9_.@/-]+/)
    .filter(Boolean);
  const meaningfulTokens = rawTokens.filter((t) => !NLP_STOP_WORDS.has(t));
  const stems = meaningfulTokens.map(porterStemWord);
  return {
    rawTokens,
    meaningfulTokens,
    stems: Array.from(new Set(stems)),
  };
}

// Canonical TF-IDF Intent Corpus Vectors for Cosine Similarity Scoring
const GCP_NLP_INTENT_CORPUS = [
  {
    id: 'SERVERLESS_TIMEOUT_5XX',
    label: 'Cloud Run / Serverless Upstream 5xx & Deadline Timeout',
    terms: {
      cloud: 1.5, run: 2.2, cloudrun: 2.5, revis: 2.0, timeout: 2.8,
      deadlin: 2.6, exceed: 2.2, '5xx': 2.8, '500': 2.2, '502': 2.2,
      '503': 2.3, '504': 2.8, gateway: 2.0, upstream: 2.4, slow: 1.8,
    },
  },
  {
    id: 'VERTEX_QUOTA_RATE_LIMIT_429',
    label: 'Vertex AI / API Quota Exhaustion & HTTP 429 Rate Limiting',
    terms: {
      '429': 3.0, quota: 2.8, rate: 2.2, limit: 2.2, exhaust: 2.6,
      resourceexhaust: 3.0, vertex: 2.4, gemini: 2.4, aiplatform: 2.5,
      throttl: 2.5, rpm: 2.0,
    },
  },
  {
    id: 'IAM_SECRET_PERMISSION_DENIED',
    label: 'Zero-Trust IAM & Secret Manager Permission Denied (403)',
    terms: {
      iam: 2.6, secret: 2.6, secretmanag: 2.8, permiss: 2.7, deni: 2.8,
      forbidden: 2.6, '401': 2.2, '403': 2.8, unauthorized: 2.5,
      principal: 2.0, access: 1.8, role: 1.9, policy: 1.9,
    },
  },
  {
    id: 'DLP_CREDENTIAL_PII_LEAK',
    label: 'Cloud DLP Secret Key, OAuth JWT & Regulated PII Exposure',
    terms: {
      dlp: 3.0, pii: 2.8, leak: 2.8, token: 2.5, bearer: 2.8, jwt: 2.7,
      apikey: 2.8, aiza: 3.0, key: 2.0, email: 2.2, unmask: 2.6,
      redact: 2.5, credenti: 2.5, webhook: 1.9,
    },
  },
  {
    id: 'DATABASE_SQL_ALLOYDB_LATENCY',
    label: 'Cloud SQL / AlloyDB Query Execution & Connection Pool Telemetry',
    terms: {
      sql: 2.6, cloudsql: 2.8, alloydb: 3.0, postgr: 2.5, mysql: 2.5,
      databas: 2.4, select: 2.2, query: 2.0, statement: 2.2, tenant: 1.8,
    },
  },
  {
    id: 'K8S_GKE_PROBE_NOISE',
    label: 'GKE Kubernetes Pod & Kubelet Healthcheck Probe Chatter',
    terms: {
      gke: 2.8, kubernet: 2.8, k8: 2.6, pod: 2.4, contain: 2.0,
      kubelet: 2.8, healthcheck: 2.8, healthz: 3.0, readyz: 2.8,
      probe: 2.6, nois: 2.2,
    },
  },
];

function computeTfIdfCosineIntent(stems = []) {
  if (!stems.length) {
    return {
      topIntentId: 'ALL_PROJECT_TELEMETRY',
      topIntentLabel: 'All Project Telemetry Streams',
      cosineSimilarity: 1.0,
      rankedIntents: [],
    };
  }
  const queryVec = {};
  for (const s of stems) {
    queryVec[s] = (queryVec[s] || 0) + 1;
  }
  const queryNorm = Math.sqrt(
    Object.values(queryVec).reduce((acc, v) => acc + v * v, 0)
  ) || 1;

  const scored = GCP_NLP_INTENT_CORPUS.map((intent) => {
    let dot = 0;
    let docNormSq = 0;
    for (const [term, weight] of Object.entries(intent.terms)) {
      docNormSq += weight * weight;
      if (queryVec[term]) {
        dot += queryVec[term] * weight;
      } else {
        // Partial prefix match for compound technical stems
        const partial = stems.find(
          (st) => st.length >= 3 && (term.startsWith(st) || st.startsWith(term))
        );
        if (partial) dot += 0.75 * weight;
      }
    }
    const docNorm = Math.sqrt(docNormSq) || 1;
    const cosine = Math.min(0.99, Number((dot / (queryNorm * docNorm)).toFixed(2)));
    return {
      id: intent.id,
      label: intent.label,
      cosine,
    };
  }).sort((a, b) => b.cosine - a.cosine);

  const best = scored[0];
  return {
    topIntentId: best && best.cosine > 0.08 ? best.id : 'CUSTOM_SEMANTIC_QUERY',
    topIntentLabel:
      best && best.cosine > 0.08
        ? best.label
        : 'Custom Multi-Entity Semantic Query',
    cosineSimilarity: best && best.cosine > 0.08 ? best.cosine : 0.78,
    rankedIntents: scored.filter((s) => s.cosine > 0).slice(0, 3),
  };
}

const CITY_TO_GCP_REGION = {
  iowa: 'us-central1',
  oregon: 'us-west1',
  virginia: 'us-east4',
  carolina: 'us-east1',
  belgium: 'europe-west1',
  london: 'europe-west2',
  frankfurt: 'europe-west3',
  netherlands: 'europe-west4',
  zurich: 'europe-west6',
  paris: 'europe-west9',
  tokyo: 'asia-northeast1',
  singapore: 'asia-southeast1',
  sydney: 'australia-southeast1',
};

function extractNlpEntities(rawText = '') {
  const text = String(rawText || '').trim();
  const lower = text.toLowerCase();
  const entities = {
    services: [],
    httpStatuses: [],
    statusClass: null,
    latency: null,
    timeWindow: null,
    regions: [],
    ips: [],
    principals: [],
    negations: [],
    severities: [],
  };

  if (!text) return entities;

  // 1. Temporal Entity Extraction ("last 30m", "past 2 hours", "since 45 minutes ago", "last 7d")
  const timeMatch = lower.match(
    /(?:in\s+the\s+|last\s+|past\s+|since\s+|within\s+)(\d+)\s*(m|min|mins|minute|minutes|h|hr|hrs|hour|hours|d|day|days)\b/
  );
  if (timeMatch) {
    const val = parseInt(timeMatch[1], 10);
    const unit = timeMatch[2][0];
    const minutesAgo =
      unit === 'd' ? val * 1440 : unit === 'h' ? val * 60 : val;
    const isoStart = new Date(Date.now() - minutesAgo * 60000).toISOString();
    entities.timeWindow = {
      raw: timeMatch[0],
      minutesAgo,
      isoStart,
      sqlInterval:
        unit === 'd'
          ? `INTERVAL ${val} DAY`
          : unit === 'h'
          ? `INTERVAL ${val} HOUR`
          : `INTERVAL ${val} MINUTE`,
    };
  }

  // 2. Latency / Duration Comparator Extraction ("over 1.5s", "slower than 800ms", "> 2 seconds", "under 50ms")
  const latMatch = lower.match(
    /(?:over|above|slower\s+than|longer\s+than|more\s+than|taking\s+over|>=|>|under|below|faster\s+than|<=|<)\s*(\d+(?:\.\d+)?)\s*(ms|millisecond|milliseconds|s|sec|secs|second|seconds)\b/
  );
  if (latMatch) {
    const isLess = /under|below|faster|<(?!=)/.test(latMatch[0]);
    const num = parseFloat(latMatch[1]);
    const unit = latMatch[2].startsWith('m') ? 'ms' : 's';
    const thresholdMs = unit === 's' ? Math.round(num * 1000) : Math.round(num);
    const thresholdSec = Number((thresholdMs / 1000).toFixed(3));
    entities.latency = {
      raw: latMatch[0],
      operator: isLess ? '<' : '>',
      thresholdMs,
      thresholdSec,
    };
  } else if (/\bslow\b|\bhigh\s+latency\b/.test(lower)) {
    entities.latency = {
      raw: 'slow (>1000ms)',
      operator: '>',
      thresholdMs: 1000,
      thresholdSec: 1.0,
    };
  }

  // 3. Negation Scope Extraction ("excluding healthchecks", "without probe", "not 200", "except info")
  const negRegex =
    /\b(?:excluding|exclude|without|except|ignore|not|!=)\s+([a-z0-9_/-]+(?:\s+[a-z0-9_/-]+)?)/g;
  let negMatch;
  while ((negMatch = negRegex.exec(lower)) !== null) {
    const phrase = negMatch[1].trim();
    if (/health|probe|healthz|readyz/.test(phrase)) {
      entities.negations.push({
        label: 'Exclude Healthchecks (/healthz, kube-probe)',
        term: 'healthz',
        lql: '-httpRequest.requestUrl:"/healthz" AND -httpRequest.userAgent:"kube-probe"',
        sql: ` COALESCE(http_request.request_url, '') NOT LIKE '%/healthz%'`,
      });
    } else if (/^200\b|ok\b/.test(phrase)) {
      entities.negations.push({
        label: 'Exclude HTTP 200 OK',
        term: '200',
        lql: '-httpRequest.status=200',
        sql: `COALESCE(http_request.status, 0) != 200`,
      });
    } else if (/info|debug/.test(phrase)) {
      entities.negations.push({
        label: 'Exclude INFO/DEBUG Severity',
        term: 'info',
        lql: 'severity>=WARNING',
        sql: `severity NOT IN ('INFO', 'DEBUG', 'DEFAULT')`,
      });
    } else {
      const cleanToken = phrase.split(/\s+/)[0].replace(/[^a-z0-9_.-]/g, '');
      if (cleanToken) {
        entities.negations.push({
          label: `Exclude "${cleanToken}"`,
          term: cleanToken,
          lql: `-textPayload:"${cleanToken}"`,
          sql: `STRPOS(LOWER(COALESCE(text_payload, '')), '${cleanToken}') = 0`,
        });
      }
    }
  }

  // 4. HTTP Status Codes & Classes
  if (/\b5xx\b|server\s+error|timeout|deadline/.test(lower)) {
    entities.statusClass = '5XX';
  } else if (/\b4xx\b/.test(lower)) {
    entities.statusClass = '4XX';
  }
  const explicitCodes = lower.match(/\b(200|400|401|403|404|409|429|500|502|503|504)\b/g);
  if (explicitCodes) {
    for (const c of explicitCodes) {
      const codeNum = parseInt(c, 10);
      if (
        !entities.negations.some((n) => n.term === String(codeNum)) &&
        !entities.httpStatuses.includes(codeNum)
      ) {
        entities.httpStatuses.push(codeNum);
      }
    }
  }
  if (/quota|rate\s+limit|resourceexhausted/.test(lower) && !entities.httpStatuses.includes(429)) {
    entities.httpStatuses.push(429);
  }
  if (/permission\s+denied|forbidden|untrusted/.test(lower) && !entities.httpStatuses.includes(403)) {
    entities.httpStatuses.push(403);
  }

  // 5. GCP Service & Resource Type NER
  if (/cloud\s*run|revision|api-gateway|webhook-ingestor/.test(lower)) {
    entities.services.push({
      label: 'Cloud Run (cloud_run_revision)',
      resourceType: 'cloud_run_revision',
      lql: 'resource.type="cloud_run_revision"',
      sql: `resource.type = 'cloud_run_revision'`,
    });
  }
  if (/\bgke\b|kubernetes|\bk8s\b|kubelet|pod/.test(lower)) {
    entities.services.push({
      label: 'GKE Kubernetes (k8s_container)',
      resourceType: 'k8s_container',
      lql: 'resource.type="k8s_container"',
      sql: `resource.type = 'k8s_container'`,
    });
  }
  if (/vertex|gemini|aiplatform/.test(lower)) {
    entities.services.push({
      label: 'Vertex AI (aiplatform.googleapis.com)',
      resourceType: 'aiplatform.googleapis.com',
      lql: '(resource.type="aiplatform.googleapis.com" OR protoPayload.serviceName="aiplatform.googleapis.com")',
      sql: `proto_payload.audit_log.service_name = 'aiplatform.googleapis.com'`,
    });
  }
  if (/alloydb|cloud\s*sql|postgres|mysql|database/.test(lower)) {
    entities.services.push({
      label: 'Cloud SQL / AlloyDB (cloudsql_database)',
      resourceType: 'cloudsql_database',
      lql: 'resource.type="cloudsql_database"',
      sql: `resource.type = 'cloudsql_database'`,
    });
  }
  if (/secret\s*manager|\biam\b|secret|permission/.test(lower)) {
    entities.services.push({
      label: 'Secret Manager & IAM',
      resourceType: 'secretmanager.googleapis.com',
      lql: '(protoPayload.serviceName="secretmanager.googleapis.com" OR protoPayload.serviceName="iam.googleapis.com")',
      sql: `proto_payload.audit_log.service_name IN ('secretmanager.googleapis.com', 'iam.googleapis.com')`,
    });
  }
  if (/load\s*balancer|envoy|edge|cdn/.test(lower)) {
    entities.services.push({
      label: 'Cloud Load Balancing (http_load_balancer)',
      resourceType: 'http_load_balancer',
      lql: 'resource.type="http_load_balancer"',
      sql: `resource.type = 'http_load_balancer'`,
    });
  }

  // 6. Region & City NER
  const regionMatches = lower.match(
    /\b(?:us|europe|asia|australia|southamerica|northamerica|me|africa)-[a-z]+\d(?:-[a-z])?\b/g
  );
  if (regionMatches) {
    entities.regions.push(...Array.from(new Set(regionMatches)));
  }
  for (const [city, reg] of Object.entries(CITY_TO_GCP_REGION)) {
    if (new RegExp(`\\b${city}\\b`).test(lower) && !entities.regions.includes(reg)) {
      entities.regions.push(reg);
    }
  }

  // 7. IPv4 & Principal Email NER
  const ipMatches = text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g);
  if (ipMatches) entities.ips.push(...Array.from(new Set(ipMatches)));

  const emailMatches = text.match(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g);
  if (emailMatches) entities.principals.push(...Array.from(new Set(emailMatches)));

  // 8. Severity NER
  if (/\bcritical\b|\bemergency\b/.test(lower)) entities.severities.push('CRITICAL');
  else if (/\berror\b|\berrors\b|\bfail|\bcrash|\bexception/.test(lower))
    entities.severities.push('ERROR');
  else if (/\bwarn|\bwarning\b/.test(lower)) entities.severities.push('WARNING');

  return entities;
}

function compileNaturalLanguageToLqlAndSql(projectId, nlQuery = '', explicitLql = '') {
  const rawQuery = String(nlQuery || '').trim();
  const tokenized = nlpTokenizeAndStem(rawQuery);
  const entities = extractNlpEntities(rawQuery);
  const intentClassification = computeTfIdfCosineIntent(tokenized.stems);

  if (explicitLql && !rawQuery) {
    return {
      lql: explicitLql.trim(),
      sql: `SELECT\n  timestamp,\n  severity,\n  resource.type AS resource_type,\n  http_request.status AS http_status,\n  http_request.latency AS latency,\n  COALESCE(text_payload, JSON_VALUE(json_payload, '$.message'), proto_payload.audit_log.method_name) AS message,\n  trace\nFROM \`${projectId}.global._Default._AllLogs\`\nWHERE timestamp >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 24 HOUR)\n  -- Explicit LQL: ${explicitLql.trim()}\nORDER BY timestamp DESC\nLIMIT 200;`,
      explanation: 'Explicit LQL AST active',
      nlpAnalysis: {
        engine: 'EXPLICIT_LQL_PASSTHROUGH',
        tokens: [],
        stems: [],
        entities,
        intent: intentClassification,
      },
    };
  }

  const lqlParts = [];
  const sqlWhere = [
    entities.timeWindow
      ? `timestamp >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), ${entities.timeWindow.sqlInterval})`
      : `timestamp >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL 24 HOUR)`,
  ];
  const notes = [];

  if (entities.timeWindow) {
    lqlParts.push(`timestamp>="${entities.timeWindow.isoStart}"`);
    notes.push(`Time Window: ${entities.timeWindow.raw}`);
  }

  if (entities.services.length === 1) {
    lqlParts.push(entities.services[0].lql);
    sqlWhere.push(entities.services[0].sql);
    notes.push(entities.services[0].label);
  } else if (entities.services.length > 1) {
    lqlParts.push(`(${entities.services.map((s) => s.lql).join(' OR ')})`);
    sqlWhere.push(`(${entities.services.map((s) => s.sql).join(' OR ')})`);
    notes.push(entities.services.map((s) => s.label).join(' + '));
  }

  if (entities.httpStatuses.length > 0) {
    if (entities.httpStatuses.length === 1) {
      const code = entities.httpStatuses[0];
      lqlParts.push(`httpRequest.status=${code}`);
      sqlWhere.push(`http_request.status = ${code}`);
    } else {
      lqlParts.push(
        `(${entities.httpStatuses.map((c) => `httpRequest.status=${c}`).join(' OR ')})`
      );
      sqlWhere.push(`http_request.status IN (${entities.httpStatuses.join(', ')})`);
    }
    notes.push(`HTTP Status: ${entities.httpStatuses.join(', ')}`);
  } else if (entities.statusClass === '5XX') {
    lqlParts.push('httpRequest.status>=500');
    sqlWhere.push(`http_request.status >= 500`);
    notes.push('HTTP 5xx Server Faults');
  } else if (entities.statusClass === '4XX') {
    lqlParts.push('(httpRequest.status>=400 AND httpRequest.status<500)');
    sqlWhere.push(`http_request.status BETWEEN 400 AND 499`);
    notes.push('HTTP 4xx Client/Auth Errors');
  }

  if (entities.severities.length > 0 && entities.httpStatuses.length === 0) {
    const sev = entities.severities[0];
    lqlParts.push(`severity>=${sev}`);
    sqlWhere.push(`severity IN ('${sev}', 'ERROR', 'CRITICAL')`);
    notes.push(`Severity >= ${sev}`);
  }

  if (entities.latency) {
    lqlParts.push(
      `httpRequest.latency${entities.latency.operator}"${entities.latency.thresholdSec}s"`
    );
    sqlWhere.push(
      `CAST(REPLACE(http_request.latency, 's', '') AS FLOAT64) ${entities.latency.operator} ${entities.latency.thresholdSec}`
    );
    notes.push(
      `Latency ${entities.latency.operator} ${entities.latency.thresholdMs}ms`
    );
  }

  if (entities.regions.length > 0) {
    const regFilter = entities.regions
      .map((r) => `resource.labels.location="${r}"`)
      .join(' OR ');
    lqlParts.push(entities.regions.length > 1 ? `(${regFilter})` : regFilter);
    sqlWhere.push(
      `JSON_VALUE(resource.labels, '$.location') IN (${entities.regions
        .map((r) => `'${r}'`)
        .join(', ')})`
    );
    notes.push(`Regions: ${entities.regions.join(', ')}`);
  }

  if (entities.ips.length > 0) {
    for (const ip of entities.ips) {
      lqlParts.push(`(httpRequest.remoteIp="${ip}" OR textPayload:"${ip}")`);
      sqlWhere.push(
        `(http_request.remote_ip = '${ip}' OR STRPOS(COALESCE(text_payload, ''), '${ip}') > 0)`
      );
    }
    notes.push(`IP: ${entities.ips.join(', ')}`);
  }

  if (entities.principals.length > 0) {
    for (const pr of entities.principals) {
      lqlParts.push(`protoPayload.authenticationInfo.principalEmail="${pr}"`);
      sqlWhere.push(
        `proto_payload.audit_log.authentication_info.principal_email = '${pr}'`
      );
    }
    notes.push(`Principal: ${entities.principals.join(', ')}`);
  }

  if (
    intentClassification.topIntentId === 'DLP_CREDENTIAL_PII_LEAK' ||
    /\bdlp\b|\bpii\b|\bleak|\bbearer\b|\baiza/i.test(rawQuery)
  ) {
    lqlParts.push(
      '(textPayload:"Bearer " OR textPayload:"AIza" OR jsonPayload.message:"token")'
    );
    sqlWhere.push(
      `REGEXP_CONTAINS(COALESCE(text_payload, TO_JSON_STRING(json_payload)), r'(Bearer eyJ|AIza[0-9A-Za-z_-]{20,}|PRIVATE KEY)')`
    );
    notes.push('DLP Secret & PII Pattern Scan');
  }

  for (const neg of entities.negations) {
    lqlParts.push(neg.lql);
    sqlWhere.push(neg.sql);
    notes.push(neg.label);
  }

  const finalLql = lqlParts.length > 0 ? lqlParts.join(' AND ') : explicitLql || '';
  const finalSql = [
    `SELECT`,
    `  timestamp,`,
    `  severity,`,
    `  resource.type AS resource_type,`,
    `  resource.labels AS resource_labels,`,
    `  http_request.status AS http_status,`,
    `  http_request.latency AS http_latency,`,
    `  COALESCE(text_payload, JSON_VALUE(json_payload, '$.message'), proto_payload.audit_log.method_name) AS clean_message,`,
    `  proto_payload.audit_log.authentication_info.principal_email AS actor_email,`,
    `  trace`,
    `FROM \`${projectId}.global._Default._AllLogs\``,
    `WHERE ${sqlWhere.join('\n  AND ')}`,
    `ORDER BY timestamp DESC`,
    `LIMIT 250;`,
  ].join('\n');

  return {
    lql: finalLql,
    sql: finalSql,
    explanation:
      notes.length > 0
        ? `${intentClassification.topIntentLabel} (${Math.round(
            intentClassification.cosineSimilarity * 100
          )}% Cosine) · ${notes.join(' · ')}`
        : 'All Project Log Streams (_Default + _Required)',
    nlpAnalysis: {
      engine: 'COMPUTATIONAL_NLP_PORTER_NER_BM25',
      tokens: tokenized.meaningfulTokens,
      stems: tokenized.stems,
      entities,
      intent: intentClassification,
    },
  };
}

