  computeL4GpuPerHourUsd: 0.56, // Compute Engine G2 NVIDIA L4 GPU ($/hr in us-central1)
  computeH100GpuPerHourUsd: 3.93, // Compute Engine A3 NVIDIA H100 GPU ($/hr)
  storageStandardGbPerMonthUsd: 0.02, // Standard GCS / PD ($/GB-mo)
