        clusters.unshift(record);
        return res.json({
          ok: true,
          cluster: record,
          message: `Provisioned HTAP Analytical Dataset & Snapshot Clone "${cloneLabel}" in ${provisionElapsedSec}s (${record.status}).`,
        });
